window.STEPS=Object.assign(window.STEPS||{},{"tb-비상중2-p073-1":{"길":"기약분수의 분모에 2와 5 이외의 소인수가 있는지 보아 무한소수를 고른다","단계":[{"제목":"기약분수의 분모 소인수 살피기","힌트":"각 분수의 분모를 소인수분해하면 어떤 소인수가 나오는가?","식":["$\\frac{3}{10}$: $10=2\\times5$","$-\\frac{15}{8}$: $8=2^{3}$","$\\frac{7}{12}$: $12=2^{2}\\times3$","$-\\frac{11}{20}$: $20=2^{2}\\times5$","$\\frac{29}{40}$: $40=2^{3}\\times5$"],"설명":"다섯 분수는 모두 기약분수이다. 기약분수의 분모에 소인수가 $2$ 나 $5$ 뿐이면 유한소수이고, 다른 소인수가 있으면 무한소수이다.","확인":null,"스킬":"N1","고비":true},{"제목":"무한소수인 분수 확인","힌트":"분모에 $2$, $5$ 이외의 소인수가 있는 분수는 어느 것인가?","식":["$\\frac{7}{12}$ 의 분모에만 소인수 $3$ 이 있다","$\\frac{7}{12}=0.58333\\cdots$ (무한소수)"],"설명":"나머지 네 분수는 $0.3,\\ -1.875,\\ -0.55,\\ 0.725$ 로 나누어떨어지는 유한소수이다.","확인":"7/12","스킬":"N6"}]},"tb-비상중2-p073-2":{"길":"순환마디는 소수점 아래에서 처음 되풀이되는 숫자 묶음으로 읽는다","단계":[{"제목":"③ 의 순환마디 읽기","힌트":"$2.592592592\\cdots$ 에서 소수점 아래 처음부터 되풀이되는 숫자 묶음은?","식":["$2.\\underline{592}\\,\\underline{592}\\,\\underline{592}\\cdots$ → 순환마디 $592$","선지의 $259$ 는 정수 부분 $2$ 를 포함해 읽은 것이다"],"설명":"순환마디는 소수점 아래에서 찾는다. 정수 부분은 마디에 넣지 않는다.","확인":"592","스킬":"N6"},{"제목":"④ 와 나머지 선지 확인","힌트":"$1.093093093\\cdots$ 의 순환마디에서 $0$ 은 포함되는가?","식":["$1.\\underline{093}\\,\\underline{093}\\cdots$ → 순환마디 $093$ (선지의 $93$ 은 틀림)","①: $25$, ②: $132$, ⑤: $203$ 은 모두 소수점 아래 처음 되풀이되는 묶음과 같다"],"설명":"소수점 아래 첫째 자리가 $0$ 이어도 그 $0$ 부터 되풀이되면 마디에 포함한다. 그래서 틀린 연결은 ③ 과 ④ 이다.","확인":null,"스킬":"N6","고비":true}]},"tb-비상중2-p073-3":{"길":"점은 순환마디의 첫 숫자와 끝 숫자 위에만 찍는다는 규칙으로 표기를 맞춘다","단계":[{"제목":"순환마디 찾기","힌트":"$5.3343434\\cdots$ 에서 소수점 아래 처음 되풀이되는 숫자 묶음은?","식":["$5.3\\,\\underline{34}\\,\\underline{34}\\,\\underline{34}\\cdots$ → 순환마디 $34$","소수점 아래 첫째 자리 $3$ 은 되풀이되지 않는다"],"설명":"소수점 아래 둘째 자리의 $3$ 부터 $34$ 가 반복된다.","확인":"34","스킬":"N6","고비":true},{"제목":"점 찍는 위치 정하기","힌트":"순환마디 $34$ 에서 점은 어느 숫자 위에 찍는가?","식":["마디의 첫 숫자 $3$ 과 끝 숫자 $4$ 위에 점을 찍는다","$5.3343434\\cdots=5.3\\dot{3}\\dot{4}$"],"설명":"순환마디가 두 자리 이상이면 첫 숫자와 끝 숫자 위에만 점을 찍는다.","확인":null,"스킬":"N6"},{"제목":"나머지 선지 점검","힌트":"나머지 선지는 점이 어디에 잘못 찍혔는가?","식":["① $0.777\\cdots=0.\\dot{7}$","② $1.941941\\cdots=1.\\dot{9}4\\dot{1}$","④ $0.053053\\cdots=0.\\dot{0}5\\dot{3}$","⑤ $-4.693693\\cdots=-4.\\dot{6}9\\dot{3}$"],"설명":"순환마디가 소수점 아래 바로 시작하면 그 마디의 앞 숫자부터 점을 찍고, 정수 부분에는 점을 찍지 않는다. 따라서 옳은 것은 ③ 이다.","확인":null,"스킬":"N6"}]},"tb-비상중2-p073-4":{"길":"나눗셈을 이어 나머지가 되풀이되는 곳을 찾아 순환마디를 정한다","단계":[{"제목":"나눗셈으로 몫 구하기","힌트":"$7\\div22$ 의 몫을 소수점 아래 셋째 자리까지 구하면?","식":["$70\\div22=3\\cdots4$, $40\\div22=1\\cdots18$, $180\\div22=8\\cdots4$","$\\frac{7}{22}=0.318\\cdots$"],"설명":"나머지에 $0$ 을 붙여 계속 $22$ 로 나눈다. 나머지가 $4$ 로 다시 나왔으므로 같은 계산이 되풀이된다.","확인":"0.318","스킬":"N6"},{"제목":"순환마디 정하기","힌트":"처음 나온 나머지 $4$ 가 다시 나온 뒤에는 몫의 숫자가 어떻게 이어지는가?","식":["나머지 $4,\\ 18,\\ 4,\\ 18,\\ \\cdots$ 이 되풀이된다","$0.3\\,\\underline{18}\\,\\underline{18}\\cdots$ → 순환마디 $18$","$\\frac{7}{22}=0.3\\dot{1}\\dot{8}$"],"설명":"몫의 첫째 자리 $3$ 은 되풀이되지 않고, 둘째 자리의 $1$ 부터 $18$ 이 반복된다.","확인":"18","스킬":"N6","고비":true}]},"tb-비상중2-p073-5":{"길":"분모의 2와 5의 지수를 같게 맞춰 분모를 10의 거듭제곱으로 만든다","단계":[{"제목":"곱할 수 a 정하기","힌트":"분모 $2^{2}\\times5$ 를 $10^{2}$ 꼴로 만들려면 어떤 수를 곱해야 하는가?","식":["$2^{2}\\times5\\times a=2^{2}\\times5^{2}=10^{2}$","$a=5$"],"설명":"$10^{2}=2^{2}\\times5^{2}$ 이므로 분모에 부족한 $5$ 를 하나 곱한다.","확인":"5","스킬":"N6","고비":true},{"제목":"분자 b 구하기","힌트":"분자에도 같은 수를 곱하면 분자는 얼마인가?","식":["$\\frac{3\\times5}{2^{2}\\times5\\times5}=\\frac{15}{10^{2}}$","$b=15$"],"설명":"분모에 곱한 수를 분자에도 똑같이 곱해야 분수의 크기가 변하지 않는다.","확인":"15","스킬":"N6"},{"제목":"유한소수 c 구하기","힌트":"분모가 $10^{2}$ 인 분수는 소수로 어떻게 쓰는가?","식":["$\\frac{15}{10^{2}}=\\frac{15}{100}=0.15$","$a=5,\\ b=15,\\ c=0.15$"],"설명":"분모가 $100$ 이면 분자의 오른쪽 끝에서 두 칸 앞에 소수점을 찍는다.","확인":"0.15","스킬":"N6"}]},"tb-비상중2-p073-6":{"길":"약분해 기약분수로 만든 뒤 분모에 2, 5 이외의 소인수가 있는 것을 고른다","단계":[{"제목":"약분하여 기약분수로 만들기","힌트":"$\\frac{35}{2^{3}\\times7}$ 을 약분하면 분모는 어떻게 되는가?","식":["② $\\frac{9}{12}=\\frac34$","③ $\\frac{6}{21}=\\frac27$","④ $\\frac{35}{2^{3}\\times7}=\\frac{5}{2^{3}}=\\frac58$","⑤ $\\frac{3\\times7}{3\\times5^{2}\\times11}=\\frac{7}{5^{2}\\times11}$"],"설명":"분모에 소인수가 있어도 분자와 약분되면 사라질 수 있다. 소인수를 보기 전에 반드시 기약분수로 만든다.","확인":"5/8","스킬":"N1","고비":true},{"제목":"분모의 소인수로 가르기","힌트":"기약분수의 분모에 $2$, $5$ 이외의 소인수가 있는 것은 어느 것인가?","식":["분모가 $2$ 와 $5$ 만의 곱: ① $2^{2}$, ② $2^{2}$, ④ $2^{3}$ → 유한소수","다른 소인수가 있다: ③ 의 $7$, ⑤ 의 $11$ → 순환소수"],"설명":"기약분수의 분모에 $2$, $5$ 이외의 소인수가 있으면 유한소수로 나타낼 수 없어 순환소수가 된다.","확인":null,"스킬":"N6"}]},"tb-비상중2-p074-1":{"길":"마디가 두 자리이므로 100을 곱해 소수점 아래를 같게 만들고 변끼리 뺀다","단계":[{"제목":"양변에 곱할 수 정하기","힌트":"순환마디가 두 자리일 때 양변에 어떤 수를 곱해야 소수점 아래가 같아지는가?","식":["$x=0.515151\\cdots$","$100x=51.515151\\cdots$ → ① 에 들어갈 수는 $100$"],"설명":"소수점을 두 자리 옮기면 소수점 아래가 $x$ 와 똑같이 $515151\\cdots$ 이 된다.","확인":null,"스킬":"N6","고비":true},{"제목":"변끼리 빼서 x 구하기","힌트":"$100x$ 에서 $x$ 를 빼면 소수점 아래는 어떻게 되는가?","식":["$100x-x=51.5151\\cdots-0.5151\\cdots$","$99x=51$ → ② $99$, ③ $51$","$x=\\frac{51}{99}=\\frac{17}{33}$"],"설명":"소수점 아래가 같은 두 식을 빼면 순환하는 부분이 없어진다.","확인":"17/33","스킬":"N6"},{"제목":"옳지 않은 칸 찾기","힌트":"$99x=51$ 에서 $x$ 는 어떤 분수인가?","식":["④ 에는 $\\frac{51}{99}$ 가 들어가야 하므로 $\\frac{51}{90}$ 은 옳지 않다"],"설명":"분모는 $x$ 의 계수 $99$ 가 된다. ⑤ 의 $\\frac{17}{33}$ 은 $\\frac{51}{99}$ 를 약분한 값이다.","확인":null,"스킬":"N6"}]},"tb-비상중2-p074-2":{"길":"소수점 아래 바로 순환하고 마디가 세 자리이므로 1000x와 x의 차를 쓴다","단계":[{"제목":"순환마디의 위치와 자릿수","힌트":"$2.731731\\cdots$ 에서 순환마디는 소수점 아래 몇 번째 자리부터이며 몇 자리인가?","식":["$x=2.\\underline{731}\\,\\underline{731}\\cdots$","소수점 아래 첫째 자리부터 순환, 마디 $731$ 은 $3$자리"],"설명":"소수점 아래 바로 순환이 시작되고 마디가 $3$ 자리이다.","확인":"3","스킬":"N6","고비":true},{"제목":"1000x 와 x 의 차","힌트":"소수점을 마디 자릿수만큼 옮긴 식에서 $x$ 를 빼면 소수점 아래가 어떻게 되는가?","식":["$1000x=2731.731731\\cdots$","$x=2.731731\\cdots$","$1000x-x=2729$"],"설명":"소수점을 세 자리 옮기면 소수점 아래가 $x$ 와 같아져 빼면 정수만 남는다.","확인":"2729","스킬":"N6"},{"제목":"다른 식과 비교","힌트":"$10x-x$ 처럼 다른 식은 빼고 나면 소수점 아래가 남는가?","식":["$10x-x=27.3173\\cdots-2.7317\\cdots$ 는 소수점 아래가 달라 소수가 남는다","$1000x-x$ 만 소수점 아래가 같아 소수점 아래가 사라진다"],"설명":"다른 선지의 두 식도 소수점 아래가 같지 않으므로 $1000x-x$ 가 가장 편리하다.","확인":null,"스킬":"N6"}]},"tb-비상중2-p074-3":{"길":"정수 부분이 있는 순환소수는 전체에서 순환하지 않는 부분을 빼 분수로 바꾼다","단계":[{"제목":"1.04 순환소수를 분수로 바꾸기","힌트":"$x=1.040404\\cdots$ 에 $100$ 을 곱해 $x$ 를 빼면 우변은 얼마인가?","식":["$100x=104.0404\\cdots$","$100x-x=104.0404\\cdots-1.0404\\cdots=103$","$99x=103$, $x=\\frac{103}{99}$"],"설명":"정수 부분 $1$ 도 $x$ 에 포함되어 있으므로 빼는 값은 $104-1=103$ 이다. $\\frac{104}{99}$ 는 정수 부분을 빼지 않아 틀린다.","확인":"103","스킬":"N6","고비":true},{"제목":"나머지 선지 검토","힌트":"$0.1\\dot{7}$ 을 분수로 바꿀 때 어떤 두 식을 빼는가?","식":["$x=0.1777\\cdots$ 에서 $100x-10x=17.77\\cdots-1.77\\cdots=16$","$90x=16$, $x=\\frac{16}{90}=\\frac{8}{45}$","① $\\frac29$, ② $\\frac{37}{99}$, ⑤ $\\frac{826}{999}$ 도 같은 방법으로 옳다"],"설명":"소수점 아래 순환하지 않는 부분이 한 자리이므로 $100x-10x$ 로 소수점 아래를 맞춘다. 따라서 옳지 않은 것은 ③ 이다.","확인":null,"스킬":"N6"}]},"tb-비상중2-p074-4":{"길":"순환하지 않는 0 때문에 100x와 10x의 차를 쓴다는 점으로 틀린 설명을 찾는다","단계":[{"제목":"표기와 순환마디 확인","힌트":"$2.0888\\cdots$ 에서 순환하는 숫자는 무엇이며 순환소수는 유리수인가?","식":["$2.0888\\cdots=2.0\\dot{8}$, 순환마디 $8$","순환소수는 분수로 나타낼 수 있으므로 유리수이다"],"설명":"①, ②, ③ 은 옳다. 소수점 아래 첫째 자리의 $0$ 은 되풀이되지 않는다.","확인":null,"스킬":"N6"},{"제목":"분수로 만들 식 정하기","힌트":"$10x-x$ 로 소수점 아래가 없어지는가?","식":["$10x=20.888\\cdots$, $x=2.0888\\cdots$ → $10x-x=18.8$ 로 소수가 남는다","$100x=208.888\\cdots$, $10x=20.888\\cdots$ → $100x-10x=188$"],"설명":"소수점 아래가 같아지려면 순환하는 $8$ 이 같은 자리에서 시작해야 한다. $x$ 에서는 둘째 자리부터, $10x$ 에서는 첫째 자리부터 시작하므로 맞지 않는다.","확인":"188","스킬":"N6","고비":true},{"제목":"분수 구하기와 선지 결론","힌트":"$90x=188$ 에서 $x$ 를 약분하면?","식":["$x=\\frac{188}{90}=\\frac{94}{45}$","⑤ 는 옳고 ④ 의 $10x-x$ 는 쓸 수 없다"],"설명":"쓰는 식은 $100x-10x$ 이므로 ④ 가 옳지 않다.","확인":null,"스킬":"N6"}]},"tb-비상중2-p074-5":{"길":"순환소수를 분수로 고친 뒤 분자를 4 에 맞춘다","단계":[{"제목":"순환소수를 분수로 바꾸기","힌트":"순환마디가 두 자리이면 몇 배를 해서 빼야 소수 부분이 사라질까?","식":["$x=0.121212\\cdots$ 로 두면 $100x=12.121212\\cdots$","$100x-x=12$ 에서 $99x=12$","$x=\\dfrac{12}{99}=\\dfrac{4}{33}$"],"설명":"순환마디가 두 자리이므로 100배한 식에서 원래 식을 빼면 소수 부분이 없어진다. 얻은 분수를 약분하면 분자가 4인 꼴이 된다.","확인":"4/33","스킬":"N6","고비":true},{"제목":"분자를 맞춰 A 구하기","힌트":"분자가 같은 두 분수가 서로 같으려면 분모는 어떻게 되어야 할까?","식":["$\\dfrac{4}{A}=\\dfrac{4}{33}$","$A=33$"],"설명":"분자가 4로 같으므로 분모도 같아야 한다. 따라서 자연수 $A$ 는 분모에 해당하는 값이다.","확인":"33","스킬":"N6"}]},"tb-비상중2-p074-6":{"길":"순환하지 않는 무한소수만 골라 유리수가 아닌 것을 정한다","단계":[{"제목":"소수의 종류 가리기","힌트":"각 수는 끝이 있는 소수일까, 같은 마디가 되풀이될까, 되풀이되지 않을까?","식":["$-0.8$, $4.12345$ 는 유한소수, $0$ 은 정수","$3.757575\\cdots=3.\\dot{7}\\dot{5}$ 는 순환소수","$0.5050050005\\cdots$ 와 $\\dfrac{\\pi}{2}$ 는 순환하지 않는 무한소수"],"설명":"ㄷ 은 0이 하나씩 늘어나며 이어져 같은 마디가 되풀이되지 않는다. $\\pi$ 는 순환하지 않는 무한소수이므로 $\\dfrac{\\pi}{2}$ 도 마찬가지다.","확인":null,"스킬":"N6","고비":true},{"제목":"유리수 판정하기","힌트":"분수로 나타낼 수 있는 수는 어느 쪽 소수일까?","식":["ㄱ, ㄴ, ㄹ, ㅁ 은 분수로 나타낼 수 있어 유리수","ㄷ, ㅂ 은 분수로 나타낼 수 없어 유리수가 아니다"],"설명":"유한소수와 순환소수는 분수로 나타낼 수 있으므로 유리수이고, 순환하지 않는 무한소수는 유리수가 아니다.","확인":null,"스킬":"N6"}]},"tb-비상중2-p075-1":{"길":"선지마다 지수법칙을 적용해 계산한 값과 비교한다","단계":[{"제목":"곱셈·거듭제곱·나눗셈 선지 계산","힌트":"곱할 때, 거듭제곱할 때, 같은 식끼리 나눌 때 지수는 각각 어떻게 될까?","식":["① $x^{2}\\times x^{4}=x^{2+4}=x^{6}$","② $(x^{3})^{3}=x^{3\\times3}=x^{9}$","③ $x^{5}\\div x^{5}=1$"],"설명":"밑이 같은 곱은 지수를 더하고, 거듭제곱의 거듭제곱은 지수를 곱한다. 같은 식끼리 나누면 1이다. 따라서 ①, ②, ③ 은 옳지 않다.","확인":null,"스킬":"A9"},{"제목":"분수·음수의 거듭제곱 계산","고비":true,"힌트":"괄호 안 전체에 제곱을 적용하면 분모·분자와 부호는 어떻게 바뀔까?","식":["④ $\\left(\\dfrac{x^{2}}{y}\\right)^{2}=\\dfrac{x^{4}}{y^{2}}$","⑤ $(-5xy^{3})^{2}=25x^{2}y^{6}$"],"설명":"④ 는 분자와 분모에 각각 제곱을 적용한 결과가 선지와 같다. ⑤ 는 $(-5)^{2}=25$ 이므로 계수가 양수여야 해서 옳지 않다. 옳은 것은 ④ 하나다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p075-2":{"길":"괄호 밖 지수를 안쪽 지수에 곱한 뒤 양변의 지수를 비교한다","단계":[{"제목":"좌변을 한 식으로 정리","힌트":"괄호 밖의 지수는 안쪽 지수에 어떻게 작용할까?","식":["$(x^{a})^{3}=x^{3a}$","$(y^{2})^{8}=y^{16}$","$x^{3a}y^{16}=x^{15}y^{b}$"],"설명":"거듭제곱의 거듭제곱은 지수를 곱한다. 정리한 좌변과 우변이 같으므로 같은 문자의 지수끼리 같다.","확인":null,"스킬":"A9"},{"제목":"지수를 비교해 a, b 구하기","고비":true,"힌트":"x 의 지수끼리, y 의 지수끼리 같으려면 a 와 b 는 얼마일까?","식":["$3a=15$ 에서 $a=5$","$16=b$ 에서 $b=16$"],"설명":"x 의 지수에서 $3a=15$ 이므로 $a$ 가 정해지고, y 의 지수에서 $b$ 가 정해진다.","확인":null,"스킬":"A3"},{"제목":"a+b 계산","힌트":"구한 a 와 b 를 더하면 얼마일까?","식":["$a+b=5+16=21$"],"설명":"두 값을 더하면 구하는 값이다.","확인":"21","스킬":"A9"}]},"tb-비상중2-p075-3":{"길":"25 와 125 를 모두 같은 소수의 거듭제곱으로 바꿔 지수끼리 계산한다","단계":[{"제목":"밑을 하나로 통일하기","고비":true,"힌트":"25 와 125 는 각각 어떤 수의 몇 제곱일까?","식":["$25=5^{2}$, $125=5^{3}$","$25^{2}=(5^{2})^{2}=5^{4}$","$125^{3}=(5^{3})^{3}=5^{9}$"],"설명":"두 수가 모두 같은 소수의 거듭제곱이므로 밑을 통일할 수 있다. 거듭제곱의 거듭제곱은 지수를 곱한다.","확인":null,"스킬":"A9"},{"제목":"나눗셈 계산 후 a 읽기","힌트":"밑이 같은 수의 나눗셈에서 나누는 쪽 지수가 더 크면 결과는 어떤 꼴일까?","식":["$5^{4}\\div5^{9}=\\dfrac{1}{5^{9-4}}=\\dfrac{1}{5^{5}}$","$\\dfrac{1}{5^{5}}=\\dfrac{1}{5^{a}}$ 에서 $a=5$"],"설명":"나누는 쪽 지수가 더 크면 두 지수의 차를 분모의 지수로 하는 분수가 된다. 분모의 지수를 주어진 식과 비교하면 $a$ 가 정해진다.","확인":"5","스킬":"A9"}]},"tb-비상중2-p075-4":{"길":"괄호 안 모든 항에 세제곱을 적용한 뒤 계수와 지수를 비교한다","단계":[{"제목":"세제곱 전개와 계수 읽기","고비":true,"힌트":"분자의 계수 2 에도 세제곱이 적용될까?","식":["$\\left(\\dfrac{2x^{a}}{y^{2}}\\right)^{3}=\\dfrac{2^{3}x^{3a}}{y^{6}}$","$=\\dfrac{8x^{3a}}{y^{6}}$"],"설명":"분수의 거듭제곱은 분자와 분모에 각각 적용되고, 계수 2 도 세제곱의 대상이다. 이 계수가 우변의 $b$ 와 같다.","확인":"8","스킬":"A9"},{"제목":"지수를 비교해 a, c 구하기","힌트":"x 의 지수와 y 의 지수를 각각 우변과 맞추면 a 와 c 는 얼마일까?","식":["$3a=12$ 에서 $a=4$","$y^{6}$ 과 $y^{c}$ 에서 $c=6$"],"설명":"정리한 좌변과 우변에서 같은 문자의 지수끼리 같다.","확인":null,"스킬":"A3"},{"제목":"a+b+c 계산","힌트":"세 값을 모두 더하면 얼마일까?","식":["$a+b+c=4+8+6=18$"],"설명":"구한 세 값을 더한다.","확인":"18","스킬":"A9"}]},"tb-비상중2-p075-5":{"길":"빈칸마다 지수법칙을 적용해 값을 구한 뒤 크기를 비교한다","단계":[{"제목":"①, ②, ③ 의 빈칸 구하기","고비":true,"힌트":"곱셈은 지수를 더하고 나눗셈은 지수를 빼면 빈칸은 각각 얼마일까?","식":["① $a^{\\square}\\times a^{5}=a^{\\square+5}=a^{9}$ 에서 $\\square=4$","② $x\\div x^{6}=\\dfrac{1}{x^{6-1}}$ 에서 $\\square=5$","③ $\\left(\\dfrac{b^{3}}{a}\\right)^{2}=\\dfrac{b^{6}}{a^{2}}$ 에서 $\\square=6$"],"설명":"②는 지수가 작은 쪽이 분자에 있으므로 분모 쪽 지수는 두 지수의 차가 된다. ③은 분자의 지수에 2를 곱한다.","확인":null,"스킬":"A9"},{"제목":"④, ⑤ 의 빈칸 구하기","힌트":"괄호 밖 지수는 안쪽 지수에 곱하고, 곱한 뒤 나누면 지수는 어떻게 될까?","식":["④ $(x^{7}y^{\\square})^{2}=x^{14}y^{2\\times\\square}$ 에서 $2\\times\\square=4$ 이므로 $\\square=2$","⑤ $a^{8}\\times a^{4}\\div a^{\\square}=a^{12-\\square}$ 에서 $12-\\square=7$ 이므로 $\\square=5$"],"설명":"④ 는 괄호 밖 지수 2 를 y 의 지수에 곱해 우변과 맞춘다. ⑤ 는 먼저 곱한 지수에서 빈칸을 뺀다.","확인":null,"스킬":"A9"},{"제목":"빈칸 수 비교","힌트":"다섯 빈칸의 수 중 가장 큰 것은 무엇일까?","식":["$4,\\ 5,\\ 6,\\ 2,\\ 5$ 중 가장 큰 수는 $6$"],"설명":"가장 큰 빈칸의 수는 ③ 에 들어가는 값이다.","확인":"6","스킬":"A9"}]},"tb-비상중2-p075-6":{"길":"2 와 5 를 짝지어 10 의 거듭제곱을 만든 뒤 자리 수를 센다","단계":[{"제목":"10 의 거듭제곱 만들기","힌트":"5 의 지수에 맞춰 2 를 몇 개 묶으면 10 이 될까?","식":["$2^{6}=2^{3}\\times2^{3}$","$2^{6}\\times5^{3}=2^{3}\\times(2\\times5)^{3}=2^{3}\\times10^{3}$"],"설명":"2 와 5 를 같은 개수로 묶으면 곱이 10 이 된다. 남는 2 의 거듭제곱은 따로 둔다.","확인":null,"스킬":"N1"},{"제목":"수 계산하기","고비":true,"힌트":"$2^{3}$ 과 $10^{3}$ 을 각각 계산해 곱하면 얼마일까?","식":["$2^{3}\\times10^{3}=8\\times1000$","$=8000$"],"설명":"$10^{3}$ 은 1 뒤에 0 이 세 개 붙은 수이므로 8 뒤에 0 을 세 개 붙인 수가 된다.","확인":"8000","스킬":"A9"},{"제목":"자릿수 세기","힌트":"8000 은 몇 자리 수일까?","식":["$8000$ 은 네 자리 수이므로 $n=4$"],"설명":"숫자의 개수를 세면 자릿수가 된다.","확인":"4","스킬":"N1"}]},"tb-비상중2-p076-1":{"길":"선지마다 곱셈·나눗셈 규칙을 적용해 계산한 값과 비교한다","단계":[{"제목":"곱셈 선지 ①, ②, ④ 계산","힌트":"계수는 계수끼리, 문자는 같은 문자끼리 곱하면 지수는 어떻게 될까?","식":["① $7a^{2}\\times2a^{7}=14a^{2+7}=14a^{9}$","② $8a^{4}\\times\\dfrac{1}{4}a^{2}b^{5}=2a^{6}b^{5}$","④ $6x^{5}y^{2}\\times\\dfrac{1}{9}x^{2}y^{2}=\\dfrac{2}{3}x^{7}y^{4}$"],"설명":"①은 지수를 곱하지 않고 더해야 하므로 선지와 다르다. ②와 ④는 선지와 같다. ④ 는 괄호의 제곱 $\\left(-\\dfrac{1}{3}xy\\right)^{2}=\\dfrac{1}{9}x^{2}y^{2}$ 을 먼저 계산한 결과다.","확인":null,"스킬":"A9"},{"제목":"나눗셈 선지 ③, ⑤ 계산","고비":true,"힌트":"분수나 괄호가 있는 식으로 나눌 때는 어떻게 바꿔 계산할까?","식":["③ $9a^{2}b^{5}\\div\\dfrac{1}{3}ab^{3}=9a^{2}b^{5}\\times\\dfrac{3}{ab^{3}}=27ab^{2}$","⑤ $(-2xy^{2})^{3}=-8x^{3}y^{6}$","⑤ $x^{7}y^{8}\\div(-8x^{3}y^{6})=-\\dfrac{1}{8}x^{4}y^{2}$"],"설명":"나눗셈은 나누는 식의 역수를 곱한다. ③ 은 계수 27 이 되고, ⑤ 는 부호가 음수이며 지수는 서로 뺀다. 둘 다 선지와 다르다.","확인":null,"스킬":"A9"},{"제목":"옳은 선지 가리기","힌트":"계산 결과가 선지와 같은 것은 어느 번호일까?","식":["옳은 것은 ②, ④"],"설명":"①, ③, ⑤ 는 계산 결과가 선지와 다르고 ②, ④ 는 같다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p076-2":{"길":"단항식을 한 식으로 정리한 뒤 문자별 지수와 계수를 비교한다","단계":[{"제목":"괄호 제곱 전개와 정리","고비":true,"힌트":"계수 3 에도 제곱이 적용되면 어떤 값이 될까?","식":["$(3xy^{b})^{2}=9x^{2}y^{2b}$","$x^{a}y\\times9x^{2}y^{2b}=9x^{a+2}y^{1+2b}$"],"설명":"괄호 안의 계수와 모든 문자에 제곱이 적용된다. 정리한 식의 계수가 우변의 $c$ 와 같다.","확인":"9","스킬":"A9"},{"제목":"지수를 비교해 a, b 구하기","힌트":"x 의 지수끼리, y 의 지수끼리 같으려면 a 와 b 는 얼마일까?","식":["$a+2=3$ 에서 $a=1$","$1+2b=9$ 에서 $b=4$"],"설명":"정리한 식과 우변 $cx^{3}y^{9}$ 의 같은 문자 지수가 각각 같다.","확인":null,"스킬":"A3"},{"제목":"a+b+c 계산","힌트":"구한 세 값을 모두 더하면 얼마일까?","식":["$a+b+c=1+4+9=14$"],"설명":"구한 세 값을 더한다.","확인":"14","스킬":"A9"}]},"tb-비상중2-p076-3":{"길":"나눗셈을 역수의 곱으로 바꾸고 계수와 문자를 따로 계산한다","단계":[{"제목":"제곱 전개와 역수의 곱","고비":true,"힌트":"$(-2ab)^{2}$ 의 계수는 얼마가 될까?","식":["$(-2ab)^{2}=4a^{2}b^{2}$","$\\dfrac{5}{9}a^{5}b^{9}\\times\\dfrac{3}{a^{3}b^{2}}\\times\\dfrac{1}{4a^{2}b^{2}}$"],"설명":"음수도 제곱하면 양수가 되고 계수 $-2$ 도 제곱된다. 나눗셈은 나누는 식의 역수를 곱하는 것으로 바꾼다.","확인":"4","스킬":"A9"},{"제목":"계수 계산","힌트":"세 분수의 곱은 얼마일까?","식":["$\\dfrac{5}{9}\\times3\\times\\dfrac{1}{4}=\\dfrac{5}{12}$"],"설명":"계수는 계수끼리 따로 곱한다.","확인":"5/12","스킬":"A9"},{"제목":"문자의 지수 정리","힌트":"a 와 b 는 지수를 각각 더하고 빼면 몇 제곱이 남을까?","식":["$a^{5-3-2}=a^{0}=1$","$b^{9-2-2}=b^{5}$","$\\dfrac{5}{12}b^{5}$"],"설명":"분자의 지수에서 분모의 지수를 빼면 a 는 지수가 0 이 되어 1 이 되고 b 만 남는다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p076-4":{"길":"곱셈·나눗셈을 앞에서부터 차례로 계산한 뒤 계수와 지수를 비교한다","단계":[{"제목":"제곱 전개와 역수의 곱","힌트":"괄호의 제곱은 계수와 지수에 어떻게 적용될까?","식":["$(-x^{a}y^{3})^{2}=x^{2a}y^{6}$","$x^{2a}y^{6}\\times\\dfrac{1}{5xy}\\times10x^{2}y^{2}$"],"설명":"음수의 제곱은 양수이므로 부호가 사라진다. 나눗셈은 역수의 곱으로 바꾼다.","확인":null,"스킬":"A9"},{"제목":"계수와 문자 지수 정리","고비":true,"힌트":"계수와 x 의 지수, y 의 지수는 각각 어떻게 계산할까?","식":["계수: $\\dfrac{10}{5}=2$","$x^{2a-1+2}=x^{2a+1}$, $y^{6-1+2}=y^{7}$","$2x^{2a+1}y^{7}$"],"설명":"분모로 간 문자는 지수를 빼고, 곱해진 문자는 지수를 더한다.","확인":null,"스킬":"A9"},{"제목":"계수·지수를 비교해 합 구하기","힌트":"우변 $bx^{5}y^{c}$ 와 비교하면 a, b, c 는 얼마일까?","식":["$b=2$, $2a+1=5$ 에서 $a=2$, $c=7$","$a+b+c=2+2+7=11$"],"설명":"정리한 식과 우변에서 계수, x 의 지수, y 의 지수가 각각 같다.","확인":"11","스킬":"A3"}]},"tb-비상중2-p076-5":{"길":"빈칸만 남기고 나머지를 반대 연산으로 넘겨 식을 세운다","단계":[{"제목":"빈칸 식을 거꾸로 세우기","힌트":"곱한 것은 나누고 나눈 것은 곱해서 빈칸을 한쪽에 두면 어떤 식이 될까?","식":["$\\square=4a^{5}b^{7}\\div12a^{4}b^{6}\\times\\dfrac{1}{2}ab^{3}$"],"설명":"빈칸을 곱하는 $12a^{4}b^{6}$ 은 우변을 나누고, 빈칸을 나누는 $\\dfrac{1}{2}ab^{3}$ 은 우변에 곱한다.","확인":null,"스킬":"C5"},{"제목":"계수 계산","고비":true,"힌트":"$4\\div12\\times\\dfrac{1}{2}$ 는 얼마일까?","식":["$4\\div12\\times\\dfrac{1}{2}=\\dfrac{4}{12}\\times\\dfrac{1}{2}=\\dfrac{1}{6}$"],"설명":"나눗셈은 역수의 곱이므로 4 와 12 를 약분한 뒤 $\\dfrac{1}{2}$ 을 곱한다.","확인":"1/6","스킬":"A9"},{"제목":"문자의 지수 정리","힌트":"a 와 b 의 지수를 각각 더하고 빼면 몇 제곱이 될까?","식":["$a^{5-4+1}=a^{2}$, $b^{7-6+3}=b^{4}$","$\\dfrac{1}{6}a^{2}b^{4}$"],"설명":"나누는 식의 지수는 빼고 곱하는 식의 지수는 더한다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p076-6":{"길":"삼각형 넓이 공식에 두 단항식을 넣고 계수와 문자를 따로 곱한다","단계":[{"제목":"넓이 공식과 계수 계산","고비":true,"힌트":"삼각형 넓이 공식에서 곱해지는 수 세 개는 무엇일까?","식":["$\\dfrac{1}{2}\\times12xy^{3}\\times8x^{2}y$","계수: $\\dfrac{1}{2}\\times12\\times8=48$"],"설명":"삼각형의 넓이는 밑변과 높이를 곱한 값의 절반이다. 계수끼리 곱할 때 $\\dfrac{1}{2}$ 을 빠뜨리지 않는다.","확인":"48","스킬":"A9"},{"제목":"문자의 지수 정리","힌트":"x 와 y 의 지수는 각각 더하면 몇 제곱이 될까?","식":["$x^{1+2}y^{3+1}=x^{3}y^{4}$","$48x^{3}y^{4}$"],"설명":"같은 문자끼리 곱하면 지수를 더한다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p077-1":{"길":"분모를 통분해 분자 전체에 곱한 뒤 문자별 계수를 읽는다","단계":[{"제목":"통분하여 한 분수로 만들기","고비":true,"힌트":"분모를 같게 하려면 첫째 분수의 분자 전체에 무엇을 곱할까?","식":["$\\dfrac{2(3x-5y)+(2x+3y)}{4}$"],"설명":"첫째 분수의 분모와 분자에 2 를 곱해 분모를 4 로 맞춘다. 분자는 괄호 전체에 곱해야 $-5y$ 도 두 배가 된다.","확인":null,"스킬":"A9"},{"제목":"분자 정리 후 약분","힌트":"분자를 정리하면 x 와 y 의 계수는 각각 얼마일까?","식":["$2(3x-5y)+(2x+3y)=8x-7y$","$\\dfrac{8x-7y}{4}=2x-\\dfrac{7}{4}y$"],"설명":"동류항끼리 더한 뒤 각 항을 4 로 나눈다.","확인":null,"스킬":"A9"},{"제목":"a−b 계산","힌트":"음수인 b 를 빼면 어떻게 될까?","식":["$a=2$, $b=-\\dfrac{7}{4}$","$a-b=2+\\dfrac{7}{4}=\\dfrac{15}{4}$"],"설명":"음수를 빼는 것은 그 수의 절댓값을 더하는 것과 같다.","확인":"15/4","스킬":"A9"}]},"tb-비상중2-p077-2":{"길":"괄호 앞 마이너스는 안의 모든 항의 부호를 바꾸고 동류항을 정리한다","단계":[{"제목":"중괄호 안 소괄호 풀기","고비":true,"힌트":"소괄호 앞의 마이너스는 안의 항들에 어떻게 작용할까?","식":["$2a-(-5a+b)=2a+5a-b$","$3a-(7a-4b)=3a-7a+4b$"],"설명":"괄호 앞의 마이너스는 괄호 안 모든 항의 부호를 바꾼다. 두 중괄호 사이의 덧셈은 부호가 바뀌지 않는다.","확인":null,"스킬":"A9"},{"제목":"동류항 정리","힌트":"a 끼리, b 끼리 계수를 더하면 얼마일까?","식":["$(2a+5a-b)+(3a-7a+4b)=7a-b-4a+4b$","$=3a+3b$"],"설명":"a 의 계수는 $7-4$, b 의 계수는 $-1+4$ 로 계산한다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p077-3":{"길":"식을 정리한 뒤 최고차항의 차수로 일차식과 이차식을 가른다","단계":[{"제목":"괄호가 있는 선지 정리","고비":true,"힌트":"괄호를 풀고 동류항을 합치면 이차항은 남을까?","식":["⑤ $x^{2}+1-(x+x^{2})=x^{2}+1-x-x^{2}$","$=1-x$"],"설명":"$x^{2}$ 항이 서로 없어지므로 최고차항이 $x$ 인 일차식이 된다.","확인":null,"스킬":"A9"},{"제목":"선지별 차수 판정","힌트":"정리한 식에서 문자의 곱이 가장 많은 항은 몇 차일까?","식":["① 일차, ② 이차, ③ 일차, ④ 이차, ⑤ 일차","이차식은 ②, ④"],"설명":"③ 은 $\\dfrac{1}{5}x-\\dfrac{3}{5}y$ 로 쓸 수 있어 일차식이다. 정리한 뒤 최고차항의 차수가 2 인 식은 ② 와 ④ 이다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p077-4":{"길":"뺄셈의 결과에 뺀 식을 다시 더해 어떤 식을 구한다","단계":[{"제목":"어떤 식의 식 세우기","힌트":"뺄셈의 결과에서 원래 식을 되찾으려면 어떤 연산을 해야 할까?","식":["$A-(-5x^{2}+x-1)=2x^{2}-3x+6$","$A=(2x^{2}-3x+6)+(-5x^{2}+x-1)$"],"설명":"어떤 식에서 빼서 결과가 나왔으므로 결과에 뺀 식을 더하면 어떤 식이 된다.","확인":null,"스킬":"C5"},{"제목":"동류항 정리","고비":true,"힌트":"이차항, 일차항, 상수항끼리 더하면 각각 얼마일까?","식":["$x^{2}$: $2-5=-3$, $x$: $-3+1=-2$, 상수항: $6-1=5$","$A=-3x^{2}-2x+5$"],"설명":"같은 차수의 항끼리 계수를 더한다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p077-5":{"길":"분배법칙과 역수의 곱으로 선지를 직접 계산해 맞는 것을 가린다","단계":[{"제목":"분배법칙 선지 ①, ②, ③","힌트":"괄호 밖의 식은 괄호 안의 모든 항에 곱해졌을까?","식":["① $5a(2a-b)=10a^{2}-5ab$","② $(-x+2y+7)(-2x)=2x^{2}-4xy-14x$","③ $a(-2a+b-3)-2a(3a+4b-1)=-8a^{2}-7ab-a$"],"설명":"①은 $b$ 항에 $5a$ 가 곱해지지 않아 선지와 다르다. ③은 $ab$ 의 계수가 $1-8=-7$ 이어서 선지와 다르다. ②는 선지와 같다.","확인":null,"스킬":"A9"},{"제목":"나눗셈 선지 ④, ⑤","고비":true,"힌트":"음수로 나누면 각 항의 부호는 어떻게 될까?","식":["④ $(12a^{2}b^{3}+4a^{3}b)\\div(-2ab)=-6ab^{2}-2a^{2}$","⑤ $\\left(6x^{5}y^{2}-\\dfrac{2}{3}x^{2}y^{3}\\right)\\div3x^{2}y=2x^{3}y-\\dfrac{2}{9}y^{2}$"],"설명":"음수로 나누면 모든 항의 부호가 바뀌므로 ④ 는 선지와 다르다. ⑤ 는 각 항을 $3x^{2}y$ 로 나눈 결과가 선지와 같다. 옳은 것은 ②, ⑤ 이다.","확인":null,"스킬":"A9"}]},"tb-비상중2-p077-6":{"길":"나눗셈을 역수의 곱으로 바꾼 뒤 부호에 주의해 정리하고 계수를 읽는다","단계":[{"제목":"분배와 역수의 곱","힌트":"$-\\dfrac{1}{2}a$ 로 나누는 것은 무엇을 곱하는 것과 같을까?","식":["$3a(a-5b)=3a^{2}-15ab$","$(7a^{2}b+ab^{2})\\times\\left(-\\dfrac{2}{a}\\right)=-14ab-2b^{2}$"],"설명":"나눗셈은 역수의 곱이며, $-\\dfrac{1}{2}a$ 의 역수는 $-\\dfrac{2}{a}$ 이다. 괄호 안 모든 항에 곱한다.","확인":null,"스킬":"A9"},{"제목":"빼기 부호 처리와 계수 읽기","고비":true,"힌트":"음수가 된 괄호를 빼면 각 항의 부호는 어떻게 될까?","식":["$3a^{2}-15ab-(-14ab-2b^{2})=3a^{2}-15ab+14ab+2b^{2}$","$=3a^{2}-ab+2b^{2}$"],"설명":"빼는 괄호 앞의 마이너스가 안의 부호를 모두 바꾼다. $ab$ 의 계수는 $-15+14$ 이다.","확인":"-1","스킬":"A9"}]},"tb-비상중2-p078-1":{"길":"부등호가 들어 있는 식만 골라 부등식을 가린다","단계":[{"제목":"부등호가 없는 선지 걸러내기","힌트":"부등호도 등호도 없는 식은 무엇이라 부를까?","식":["① $a-3$, ④ $x-(3x-1)$ 은 부등호도 등호도 없는 다항식","② $2\\times7-1=13$ 은 등호가 있는 등식"],"설명":"다항식은 부등호가 없고, 등식은 등호로 두 식이 같음을 나타낸다. 둘 다 부등식이 아니다.","확인":null,"스킬":"C7"},{"제목":"부등호가 있는 선지 확인","고비":true,"힌트":"부등호가 있으면 식이 참인지 거짓인지와 관계가 있을까?","식":["③ $5>1$","⑤ $4-\\dfrac{x}{2}\\le1$","③, ⑤ 는 부등호가 있는 부등식"],"설명":"③ 처럼 문자가 없고 참인 식이어도 부등호로 크기를 나타낸 식이면 부등식이다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p078-2":{"길":"문장을 부분으로 쪼개 식으로 옮기고 '크지 않다'를 부등호로 바꾼다","단계":[{"제목":"좌변을 식으로 옮기기","힌트":"x 의 7배에 2를 더한 수는 어떤 식일까?","식":["$x$ 의 7배 $\\to 7x$","$7x$ 에 2를 더하면 $7x+2$"],"설명":"'7배'는 곱셈, '더하면'은 덧셈이다. 7배를 한 뒤 2를 더하므로 $7x$ 전체에 2를 더한다.","확인":null,"스킬":"C7"},{"제목":"'크지 않다'의 부등호","고비":true,"힌트":"'크지 않다'는 작다와 같다 중 무엇을 포함할까?","식":["'$-1$ 보다 크지 않다' $\\to \\le-1$","$7x+2\\le-1$"],"설명":"크지 않다는 작거나 같다는 뜻이므로 등호가 들어간 부등호를 쓴다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p078-3":{"길":"선지의 x 에 2를 대입해 양변을 계산하고 참인 것을 찾는다","단계":[{"제목":"①, ②, ③ 에 대입","힌트":"x 자리에 2를 넣으면 양변은 각각 얼마가 될까?","식":["① $2+4=6$ 이므로 $6>7$ 거짓","② $6-2=4$ 이므로 $4<4$ 거짓","③ $2\\times2+7=11$ 이므로 $11<10$ 거짓"],"설명":"대입한 값이 부등호의 방향과 맞는지 비교한다. 세 선지는 모두 맞지 않는다.","확인":null,"스킬":"C7"},{"제목":"④, ⑤ 에 대입","고비":true,"힌트":"양변을 각각 계산한 뒤 부등호에 맞는지 비교하면 어떻게 될까?","식":["④ $-3\\times2+1=-5$, $2\\times2-4=0$ 이므로 $-5\\le0$ 참","⑤ $\\dfrac{1}{4}\\times2-1=-\\dfrac{1}{2}$, $3-2=1$ 이므로 $-\\dfrac{1}{2}\\ge1$ 거짓"],"설명":"음수를 곱한 값의 부호에 주의해 양변을 계산한다. 참이 되는 것은 ④ 하나다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p078-4":{"길":"x 의 값을 하나씩 대입해 부등식이 참인 값을 찾아 더한다","단계":[{"제목":"x 값을 하나씩 대입","고비":true,"힌트":"양변의 값이 같을 때도 부등호가 ≤ 이면 참일까?","식":["$x=-1$: $-3\\le-1$ 참, $x=0$: $1\\le2$ 참","$x=1$: $5\\le5$ 참 (등호 성립)","$x=2$: $9\\le8$ 거짓, $x=3$: $13\\le11$ 거짓"],"설명":"부등호 $\\le$ 는 두 값이 같을 때도 성립한다. 참이 되게 하는 x 의 값은 세 개다.","확인":null,"스킬":"C7"},{"제목":"참인 x 값의 합","힌트":"참이 되는 x 의 값을 모두 더하면 얼마일까?","식":["$-1+0+1=0$"],"설명":"참이 되는 값만 더한다. 음수와 양수가 서로 상쇄된다.","확인":"0","스킬":"C7"}]},"tb-비상중2-p078-5":{"길":"음수를 곱하거나 나누는 단계가 있는 식을 찾아 부등호 방향을 비교한다","단계":[{"제목":"①~④ 의 부등호 방향","힌트":"양수를 더하거나 곱해도 부등호의 방향은 바뀔까?","식":["① $a+7<b+7$, ② $2a-1<2b-1$","③ $a-\\dfrac{5}{2}<b-\\dfrac{5}{2}$, ④ $\\dfrac{a}{3}+4<\\dfrac{b}{3}+4$"],"설명":"양수를 더하고 빼거나 양수를 곱하고 나누면 부등호의 방향은 그대로다. ①~④ 는 모두 $<$ 이다.","확인":null,"스킬":"C7"},{"제목":"⑤ 의 부등호 방향","고비":true,"힌트":"$2-a$ 에는 $a$ 에 어떤 수가 곱해져 있을까?","식":["$a<b$ 에서 $-a>-b$","$2-a>2-b$, $\\dfrac{2-a}{9}>\\dfrac{2-b}{9}$"],"설명":"$2-a$ 에서 $a$ 에 $-1$ 이 곱해져 있으므로 부등호의 방향이 바뀐다. 따라서 ⑤ 만 $>$ 이다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p078-6":{"길":"음수를 곱하거나 나누는 순간에만 부등호 방향이 바뀐다는 점으로 하나씩 가린다","단계":[{"제목":"양수로 나누는 ㄱ, ㄷ","힌트":"양수를 더하거나 나눌 때 부등호의 방향은 어떻게 될까?","식":["ㄱ. $a-5>b-5$ 에서 $a>b$ 이므로 옳다","ㄷ. $\\dfrac{a}{2}-1<\\dfrac{b}{2}-1$ 에서 $\\dfrac{a}{2}<\\dfrac{b}{2}$ 이므로 $a<b$ 이다"],"설명":"ㄷ 은 양수 2 를 곱해도 방향이 그대로여서 $a<b$ 이다. 주어진 결론 $a>b$ 와 방향이 달라 옳지 않다.","확인":null,"스킬":"C7"},{"제목":"음수를 곱하는 ㄴ, ㄹ, ㅁ","고비":true,"힌트":"음수로 나누거나 곱하면 부등호의 방향은 어떻게 될까?","식":["ㄴ. $-4a\\le-4b$ 에서 $a\\ge b$ 이므로 옳다","ㄹ. $-2a\\ge-2b$ 에서 $a\\le b$ 이므로 옳지 않다","ㅁ. $-\\dfrac{a}{3}<-\\dfrac{b}{3}$ 에서 $a>b$ 이므로 옳다"],"설명":"음수로 나누거나 곱할 때 부등호의 방향이 바뀐다. 따라서 옳은 것은 ㄱ, ㄴ, ㅁ 이다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p079-1":{"길":"모든 항을 한쪽으로 옮겨 정리했을 때 x 가 남는지로 일차부등식을 판정한다","단계":[{"제목":"양변에 문자가 있는 ②, ⑤ 정리","힌트":"모든 항을 한쪽으로 옮겨 정리하면 x 의 최고 차수는 얼마가 될까?","식":["② $7-x-x-1>0$, $-2x+6>0$","⑤ $x^{2}+x-x^{2}+x-4\\ge0$, $2x-4\\ge0$"],"설명":"⑤ 는 $x^{2}$ 항이 없어지고 일차항만 남는다. 정리했을 때 일차식이 되면 일차부등식이다. ①, ④ 도 처음부터 일차다.","확인":null,"스킬":"C7"},{"제목":"③ 정리","고비":true,"힌트":"양변의 $3x$ 를 이항하면 x 는 남을까?","식":["$3x+1>-1+3x$","$3x-3x>-1-1$, $0>-2$"],"설명":"양변의 $3x$ 가 모두 없어져 x 가 사라지므로 일차부등식이 아니다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p079-2":{"길":"수직선에서 해를 읽고, 선지의 부등식을 풀어 같은 해를 찾는다","단계":[{"제목":"수직선에서 해 읽기","힌트":"점이 색칠되어 있으면 그 수를 포함할까?","식":["색칠한 점 $3$ 에서 오른쪽으로 뻗는다","$x\\ge3$"],"설명":"색칠한 점은 그 수를 포함한다는 뜻이므로 등호가 들어간다. 오른쪽 방향은 3 보다 큰 쪽이다.","확인":null,"스킬":"G6"},{"제목":"①, ②, ③ 의 해","힌트":"각 부등식의 x 를 한쪽에 모으면 해는 무엇일까?","식":["① $x-2>1$ 에서 $x>3$","② $2x-4\\le-x+5$ 에서 $3x\\le9$, $x\\le3$","③ $5-x\\ge x+1$ 에서 $4\\ge2x$, $x\\le2$"],"설명":"① 은 등호가 없는 $x>3$ 이고, ② 와 ③ 은 부등호 방향이 반대다. 세 선지 모두 그림과 다르다.","확인":null,"스킬":"C7"},{"제목":"④, ⑤ 의 해","고비":true,"힌트":"음수로 양변을 나누면 부등호는 어떻게 될까?","식":["④ $-(x-4)\\le x-2$ 에서 $-x+4\\le x-2$, $-2x\\le-6$, $x\\ge3$","⑤ $4(x-1)\\ge3(x+1)$ 에서 $4x-4\\ge3x+3$, $x\\ge7$"],"설명":"④ 는 $-2$ 로 나누면서 부등호의 방향이 바뀌어 $x\\ge3$ 이 되어 그림과 같다. ⑤ 는 $x\\ge7$ 이다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p079-3":{"길":"양변에 분모의 최소공배수를 곱해 분모를 없앤 뒤 일차부등식을 푼다","단계":[{"제목":"분모를 없애도록 양변에 곱하기","고비":true,"힌트":"분모 6 과 3 을 모두 없애는 수를 곱할 때, −1 에도 곱해야 할까?","식":["양변에 $6$ 을 곱한다","$3x+1-6\\ge4x$"],"설명":"정수인 $-1$ 에도 같은 수를 곱해야 한다. $\\dfrac{2}{3}x$ 에 곱하면 $4x$ 가 된다.","확인":null,"스킬":"C7"},{"제목":"정리해 x 의 범위 구하기","힌트":"x 항을 한쪽에 모아 x 의 계수가 음수이면 부등호는 어떻게 될까?","식":["$3x-5\\ge4x$","$-x\\ge5$, $x\\le-5$"],"설명":"음수 $-1$ 로 양변을 나누므로 부등호의 방향이 바뀐다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p079-4":{"길":"소수를 분수로 바꾸고 분모의 최소공배수를 곱해 푼 뒤 정수를 고른다","단계":[{"제목":"공통 분모 정하기","힌트":"소수 $0.2$ 를 분수로 바꾸면 분모는 무엇이며, 3 과의 최소공배수는 얼마일까?","식":["$-0.2x=-\\dfrac{1}{5}x$","분모 $3$ 과 $5$ 의 최소공배수는 $15$"],"설명":"$0.2=\\dfrac{1}{5}$ 이므로 분모는 3 과 5 이다. 두 분모의 최소공배수를 양변에 곱하면 모든 분모가 없어진다.","확인":"15","스킬":"C7"},{"제목":"양변에 곱해 분모 없애기","고비":true,"힌트":"−1 과 2 에도 같은 수를 곱해야 할까?","식":["$5(2x-4)-15\\ge-3x+30$"],"설명":"$\\dfrac{2x-4}{3}$ 에는 5 가 곱해지고, 정수 $-1$ 과 $2$ 에도 모두 곱해야 한다.","확인":null,"스킬":"C7"},{"제목":"x 의 범위 구하기","힌트":"x 항은 왼쪽, 수는 오른쪽으로 모으면 x 의 범위는 어떻게 될까?","식":["$10x-20-15\\ge-3x+30$","$13x\\ge65$, $x\\ge5$"],"설명":"괄호를 풀어 이항한 뒤 양수 13 으로 나누므로 부등호의 방향은 그대로다.","확인":null,"스킬":"C7"},{"제목":"가장 작은 정수 고르기","힌트":"x 의 범위에 포함되는 가장 작은 정수는 무엇일까?","식":["$x\\ge5$ 이므로 가장 작은 정수는 $5$"],"설명":"경계의 수가 범위에 포함되므로 그 수가 가장 작은 정수다.","확인":"5","스킬":"C7"}]},"tb-비상중2-p079-5":{"길":"'넘지 않는다'를 부등호로 바꿔 식을 세우고 선지의 값을 비교한다","단계":[{"제목":"'넘지 않는다'를 부등호로 옮기기","고비":true,"힌트":"'넘지 않는다'는 두 수가 같은 경우를 포함할까?","식":["처음 자연수를 $x$ 라 하면","4배 한 후 1을 뺀 수 $4x-1$, 2배 한 후 9를 더한 수 $2x+9$","$4x-1\\le2x+9$"],"설명":"넘지 않는다는 같거나 작다는 뜻이므로 등호가 들어간 부등호 $\\le$ 를 쓴다.","확인":null,"스킬":"C7"},{"제목":"부등식의 해 구하기","힌트":"$x$ 항은 좌변으로, 수는 우변으로 옮기면 어떤 식이 될까?","식":["$4x-2x\\le9+1$","$2x\\le10$, $x\\le5$"],"설명":"이항해 정리한 뒤 양변을 2로 나눈다. 처음 자연수는 5 이하이다.","확인":"5","스킬":"C7"},{"제목":"조건에 맞지 않는 값 찾기","힌트":"선지의 값 중 위에서 구한 범위를 벗어나는 것은 무엇일까?","식":["선지의 값은 $2,3,4,5,6$","$x\\le5$ 를 만족하지 않는 값은 $6$"],"설명":"5 이하의 자연수는 처음 자연수가 될 수 있고, 5보다 큰 값은 될 수 없다.","확인":"6","스킬":"C7"}]},"tb-비상중2-p079-6":{"길":"교통비를 더한 마트 비용이 편의점 비용보다 적어야 유리하다고 식을 세운다","단계":[{"제목":"두 곳의 총비용 식으로 나타내기","힌트":"마트에서는 초콜릿 값 말고 또 무엇을 내야 할까?","식":["초콜릿을 $x$ 개 산다고 하면","편의점: $1500x$ 원","마트: $1100x+2200$ 원"],"설명":"마트에서는 초콜릿 값에 왕복 교통비 2200원을 더해야 총비용이 된다.","확인":null,"스킬":"C7"},{"제목":"유리한 조건의 부등호 정하기","고비":true,"힌트":"마트 비용과 편의점 비용이 같으면 마트가 유리할까?","식":["마트가 유리하다 $\\to$ 마트 비용이 더 적다","$1100x+2200<1500x$"],"설명":"비용이 같으면 유리하다고 할 수 없으므로 등호가 없는 부등호를 쓴다.","확인":null,"스킬":"C7"},{"제목":"부등식 풀기","힌트":"$x$ 항을 한쪽으로 모으면 계수는 얼마가 될까?","식":["$2200<1500x-1100x$, $2200<400x$","$x>\\frac{2200}{400}=\\frac{11}{2}$"],"설명":"$x$ 항을 우변으로 모으고 양변을 400으로 나눈다.","확인":"5.5","스킬":"C7"},{"제목":"조건을 만족하는 최소 개수 정하기","힌트":"5.5 보다 큰 자연수 중 가장 작은 것은 무엇일까?","식":["$x>5.5$ 를 만족하는 가장 작은 자연수는 $6$"],"설명":"개수는 자연수여야 하므로 5.5 보다 큰 첫 자연수가 최소 개수이다. 이 개수 이상 사면 마트가 유리하다.","확인":"6","스킬":"C7"}]},"tb-비상중2-p080-1":{"길":"우변을 좌변으로 옮겨 정리했을 때 미지수가 2개인 일차식인 등식을 고른다","단계":[{"제목":"등식이 아닌 보기 가려내기","힌트":"방정식이 되려면 반드시 무엇이 있어야 할까?","식":["ㄱ $4x-3y$ 에는 등호가 없다","ㄱ 은 방정식이 아닌 다항식"],"설명":"방정식은 등호가 있는 등식이다. 등호가 없는 ㄱ 은 제외한다.","확인":null,"스킬":"A10"},{"제목":"ㄴ, ㄷ, ㄹ 정리하기","힌트":"우변을 모두 좌변으로 옮기면 각 식은 어떻게 될까?","식":["ㄴ $2x-y+3=0$ 은 미지수 2개","ㄷ $-x+3y=2-2x$ $\\to$ $x+3y-2=0$ 은 미지수 2개","ㄹ $3x-7=5x-7$ $\\to$ $-2x=0$ 은 미지수 1개"],"설명":"이항해 정리한 뒤 남는 미지수의 개수를 센다. ㄹ 은 $y$ 가 사라져 미지수가 1개이다.","확인":null,"스킬":"A10"},{"제목":"ㅁ, ㅂ 의 차수 확인하기","고비":true,"힌트":"정리하면 $x^{2}$ 항이 남을까, 사라질까?","식":["ㅁ $x^{2}+5y=x^{2}-3x$ $\\to$ $3x+5y=0$ 은 일차","ㅂ $x^{2}+2x-8=0$ 은 이차방정식이고 미지수 1개"],"설명":"ㅁ 은 양변의 $x^{2}$ 이 지워져 일차가 된다. ㅂ 은 $x^{2}$ 이 남고 $y$ 도 없다.","확인":null,"스킬":"A10"},{"제목":"조건에 맞는 보기 모으기","힌트":"미지수가 2개이면서 일차인 등식은 어느 것일까?","식":["미지수가 2개인 일차방정식: ㄴ, ㄷ, ㅁ"],"설명":"등식이고 정리했을 때 미지수가 2개이며 일차인 것만 남는다.","확인":null,"스킬":"A10"}]},"tb-비상중2-p080-2":{"길":"x, y 자리에 순서대로 대입해 좌변이 2가 되지 않는 순서쌍을 찾는다","단계":[{"제목":"①, ② 를 대입해 좌변 계산","힌트":"$x$ 자리에 앞의 수, $y$ 자리에 뒤의 수를 넣으면 $5x-3y$ 는 얼마일까?","식":["① $5\\times(-5)-3\\times(-9)=-25+27=2$","② $5\\times(-3)-3\\times(-7)=-15+21=6$"],"설명":"좌변이 우변 2와 같으면 해이고, 다르면 해가 아니다. ① 은 해이고 ② 는 해가 아니다.","확인":null,"스킬":"A10"},{"제목":"③, ④, ⑤ 를 대입해 좌변 계산","고비":true,"힌트":"좌변의 값이 2가 되지 않는 것은 어느 것일까?","식":["③ $5\\times1-3\\times1=2$","④ $5\\times3-3\\times5=0$","⑤ $5\\times4-3\\times6=2$"],"설명":"③, ⑤ 는 해이고 ④ 는 해가 아니다. 해가 아닌 것은 ②, ④ 이다.","확인":null,"스킬":"A10"}]},"tb-비상중2-p080-3":{"길":"y 를 x 로 나타내고 x 에 자연수를 차례로 넣어 y 도 자연수인 쌍을 센다","단계":[{"제목":"x 에 자연수를 차례로 대입","고비":true,"힌트":"$x$ 가 커지면 $y$ 는 어떻게 변하고, 언제 자연수가 아니게 될까?","식":["$y=13-3x$","$x=1,2,3,4$ 일 때 $y=10,7,4,1$","$x=5$ 일 때 $y=-2$ 로 자연수가 아님"],"설명":"$x$ 가 커질수록 $y$ 는 작아지므로 $y$ 가 자연수가 아니게 되면 더 볼 필요가 없다.","확인":null,"스킬":"P4"},{"제목":"해의 개수 세기","힌트":"$x$, $y$ 가 모두 자연수인 순서쌍은 몇 쌍일까?","식":["$(1,10),(2,7),(3,4),(4,1)$"],"설명":"두 값이 모두 자연수인 순서쌍의 수가 해의 개수이다.","확인":"4","스킬":"P4"}]},"tb-비상중2-p080-4":{"길":"해를 식에 대입해 a 에 대한 일차방정식을 만들어 푼다","단계":[{"제목":"해를 대입해 a 의 식 만들기","고비":true,"힌트":"$x$ 자리에 $-2$, $y$ 자리에 $2$ 를 넣으면 좌변은 $a$ 에 대한 어떤 식이 될까?","식":["$a\\times(-2)-5\\times2=-14$","$-2a-10=-14$"],"설명":"해는 방정식을 참이 되게 하는 값이므로 $x$, $y$ 에 그대로 대입한다.","확인":null,"스킬":"A10"},{"제목":"a 의 값 구하기","힌트":"상수항을 우변으로 옮긴 뒤 양변을 $-2$ 로 나누면 어떻게 될까?","식":["$-2a=-14+10=-4$","$a=2$"],"설명":"$-10$ 을 이항하면 $-2a=-4$ 이다. 양변을 $-2$ 로 나누면 $a$ 가 나온다.","확인":"2","스킬":"A10"}]},"tb-비상중2-p080-5":{"길":"두 문장을 각각 식으로 옮기고 같은 두 식이 묶인 선지를 고른다","단계":[{"제목":"합의 조건을 식으로 옮기기","힌트":"'합이 11이다'는 어떤 등식일까?","식":["$x$ 와 $y$ 의 합 $\\to x+y$","$x+y=11$"],"설명":"합은 덧셈이다. ④, ⑤ 의 $x=y+11$ 은 차가 11이라는 뜻이어서 제외한다.","확인":null,"스킬":"C7"},{"제목":"3배에서 뺀다는 조건을 식으로 옮기기","고비":true,"힌트":"'$x$ 의 3배에서 $y$ 를 뺀다'에서 빼지는 수는 무엇일까?","식":["$x$ 의 3배 $\\to 3x$","$3x$ 에서 $y$ 를 뺀다 $\\to 3x-y$","$3x-y=9$"],"설명":"빼지는 수가 $3x$ 이고 빼는 수가 $y$ 이다. 두 식 $x+y=11$, $3x-y=9$ 를 묶은 선지를 고른다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p080-6":{"길":"(1, 2)를 각 식의 x, y 에 대입해 두 식이 모두 성립하는 연립방정식을 찾는다","단계":[{"제목":"ㄱ, ㄴ 에 대입하기","고비":true,"힌트":"한 식만 성립하면 그 순서쌍은 연립방정식의 해일까?","식":["ㄱ $1+2=3$, $2\\times1-3\\times2=-4$ 로 두 식 모두 성립","ㄴ $1+2\\times2=5$ 는 성립, $2\\times1-3\\times2=-4\\ne4$ 로 불성립"],"설명":"연립방정식의 해는 두 식을 모두 만족해야 한다. 한 식이라도 성립하지 않으면 해가 아니다.","확인":null,"스킬":"A10"},{"제목":"ㄷ, ㄹ 에 대입하기","힌트":"첫째 식에서 이미 맞지 않으면 둘째 식도 확인해야 할까?","식":["ㄷ $3\\times1+2\\times2=7\\ne-1$ 로 불성립","ㄹ $3\\times1-2=1$, $1-2\\times2=-3$ 으로 두 식 모두 성립"],"설명":"ㄷ 은 첫째 식에서 이미 맞지 않는다. 두 식이 모두 성립하는 것은 ㄱ 과 ㄹ 이다.","확인":null,"스킬":"A10"}]},"tb-비상중2-p081-1":{"길":"①을 x 에 대해 정리하고 ②에 대입해 y, x 를 차례로 구한다","단계":[{"제목":"①을 x 에 대한 식으로 나타내기","힌트":"$x-y=3$ 에서 $y$ 를 우변으로 옮기면 $y$ 앞의 계수는 얼마일까?","식":["$x-y=3$ 에서 $x=y+3$","$x=ay+3$ 과 비교하면 $a=1$"],"설명":"$y$ 를 우변으로 옮기면 $x=y+3$ 이다. $y$ 앞의 계수가 $a$ 이다.","확인":"1","스킬":"A10"},{"제목":"③을 ②에 대입해 y 구하기","고비":true,"힌트":"②의 $x$ 자리에 $y+3$ 을 넣고 괄호를 풀면 $y$ 의 계수는 얼마가 될까?","식":["$3(y+3)+2y=19$","$3y+9+2y=19$, $5y=10$","$b=5$, $y=2$ 이므로 $c=2$"],"설명":"$x$ 대신 $y+3$ 을 넣으면 $y$ 에 대한 식이 된다. 괄호를 풀고 $y$ 항을 합친 계수가 $b$ 이다.","확인":"2","스킬":"A10"},{"제목":"x 의 값과 네 수의 합","힌트":"$y=2$ 를 ③에 넣으면 $x$ 는 얼마이고, 네 수의 합은 얼마일까?","식":["$x=2+3=5$, 즉 $d=5$","$a+b+c+d=1+5+2+5$"],"설명":"구한 $y$ 의 값을 ③에 대입해 $x$ 를 구하면 $d$ 가 나온다. 네 수를 모두 더한다.","확인":"13","스킬":"A10"}]},"tb-비상중2-p081-2":{"길":"y 의 계수를 같게 맞춘 뒤 부호에 따라 더할지 뺄지 정한다","단계":[{"제목":"y 의 계수 맞추기","힌트":"㉡에 어떤 수를 곱하면 $y$ 의 계수가 ㉠과 같아질까?","식":["㉠의 $y$ 계수 $-3$, ㉡의 $y$ 계수 $-1$","㉡$\\times3$: $6x-3y=3$"],"설명":"㉡에 3을 곱해 $y$ 의 계수를 $-3$ 으로 맞춘다.","확인":null,"스킬":"A10"},{"제목":"더할지 뺄지 정하기","고비":true,"힌트":"$y$ 의 계수의 부호가 같을 때 $y$ 를 없애려면 더할까, 뺄까?","식":["㉠$-$㉡$\\times3$: $(5x-3y)-(6x-3y)=-1-3$","$-x=-4$ 로 $y$ 가 없어짐"],"설명":"계수의 부호가 같으므로 두 식을 빼야 $y$ 가 사라진다. 더하면 $-6y$ 가 남는다.","확인":null,"스킬":"A10"}]},"tb-비상중2-p081-3":{"길":"괄호를 풀어 ax+by=c 꼴로 정리한 뒤 대입으로 y, x 를 차례로 구한다","단계":[{"제목":"괄호를 풀어 정리하기","고비":true,"힌트":"분배법칙으로 괄호를 풀고 같은 문자끼리 모으면 두 식은 어떻게 될까?","식":["$5x-5y-2x=7$ $\\to$ $3x-5y=7$","$4x-3x+6y=10$ $\\to$ $x+6y=10$"],"설명":"괄호 앞의 수를 각 항에 곱한다. 둘째 식은 $-3(x-2y)=-3x+6y$ 이다.","확인":null,"스킬":"A10"},{"제목":"대입으로 y 구하기","힌트":"둘째 식을 $x=\\cdots$ 꼴로 바꿔 첫째 식에 넣으면 $y$ 에 대한 식은 어떻게 될까?","식":["$x=10-6y$","$3(10-6y)-5y=7$, $30-23y=7$","$-23y=-23$, $y=1$"],"설명":"$x$ 의 계수가 1인 둘째 식을 $x$ 에 대해 정리해 첫째 식에 대입한다.","확인":"1","스킬":"A10"},{"제목":"x 구하고 선지 고르기","힌트":"$y=1$ 을 $x=10-6y$ 에 넣으면 $x$ 는 얼마일까?","식":["$x=10-6\\times1=4$","$x=4,\\ y=1$"],"설명":"구한 $y$ 의 값을 대입해 $x$ 를 구한다. 이 해와 같은 선지를 고른다.","확인":null,"스킬":"A10"}]},"tb-비상중2-p081-4":{"길":"양변에 적당한 수를 곱해 정수 계수로 바꾼 뒤 소거해 x, y 를 구한다","단계":[{"제목":"정수 계수로 바꾸기","고비":true,"힌트":"소수와 분수가 섞인 두 식의 계수를 정수로 만들려면 각각 몇 배 해야 할까?","식":["첫째 식 $\\times10$: $2x+5y=8$","둘째 식 $\\times20$: $8x+5y=2$"],"설명":"소수 첫째 자리는 10배 한다. 분모 5, 4, 10 의 최소공배수는 20 이므로 둘째 식은 20배 한다.","확인":null,"스킬":"A10"},{"제목":"y 를 없애 x 구하기","힌트":"$y$ 의 계수가 같으므로 두 식을 빼면 무엇이 남을까?","식":["$(8x+5y)-(2x+5y)=2-8$","$6x=-6$, $x=-1$"],"설명":"$y$ 의 계수가 부호까지 같으므로 두 식을 빼서 $y$ 를 없앤다.","확인":"-1","스킬":"A10"},{"제목":"y 의 값 구하기","힌트":"$x=-1$ 을 $2x+5y=8$ 에 넣으면 $y$ 는 얼마일까?","식":["$-2+5y=8$, $5y=10$","$y=2$"],"설명":"구한 $x$ 를 계수가 작은 첫째 식에 대입한다.","확인":"2","스킬":"A10"},{"제목":"pq 의 값 구하기","힌트":"해가 $x=p$, $y=q$ 이므로 곱은 얼마일까?","식":["$p=-1$, $q=2$","$pq=(-1)\\times2=-2$"],"설명":"해의 $x$ 값이 $p$, $y$ 값이 $q$ 이다. 두 수를 곱한다.","확인":"-2","스킬":"A10"}]},"tb-비상중2-p081-5":{"길":"A=B=C 를 A=C, B=C 로 나눠 연립방정식을 만들어 푼다","단계":[{"제목":"연립방정식으로 나누기","고비":true,"힌트":"세 식이 모두 같으니 가장 간단한 식과 각각 짝지으면 어떤 두 식이 될까?","식":["$x+3y-7=2x-y$","$4x-5y+2=2x-y$"],"설명":"$A=B=C$ 는 $A=C$, $B=C$ 로 나눌 수 있다. 가장 간단한 $2x-y$ 를 두 번 쓴다.","확인":null,"스킬":"A10"},{"제목":"ax+by=c 꼴로 정리","힌트":"미지수는 좌변으로, 수는 우변으로 옮기면 두 식은 어떻게 될까?","식":["$x+3y-7=2x-y$ $\\to$ $-x+4y=7$","$4x-5y+2=2x-y$ $\\to$ $2x-4y=-2$, 즉 $x-2y=-1$"],"설명":"첫째 식은 $x-2x+3y+y=7$ 로 모은다. 둘째 식은 양변을 2로 나눠 간단히 한다.","확인":null,"스킬":"A10"},{"제목":"두 식을 더해 y 구하기","힌트":"$x$ 의 계수가 서로 반대이므로 더하면 무엇이 남을까?","식":["$(-x+4y)+(x-2y)=7+(-1)$","$2y=6$, $y=3$"],"설명":"$x$ 의 계수가 $-1$ 과 $1$ 이므로 더하면 $x$ 가 사라진다.","확인":"3","스킬":"A10"},{"제목":"x 의 값 구하기","힌트":"$y=3$ 을 $x-2y=-1$ 에 넣으면 $x$ 는 얼마일까?","식":["$x-6=-1$","$x=5$"],"설명":"구한 $y$ 를 계수가 간단한 둘째 식에 대입한다.","확인":null,"스킬":"A10"}]},"tb-비상중2-p081-6":{"길":"작은 수와 큰 수를 x, y 로 두고 문장 순서대로 두 식을 세워 푼다","단계":[{"제목":"두 수를 문자로 놓고 식 세우기","고비":true,"힌트":"'작은 수의 3배에서 큰 수를 뺀다'를 순서대로 쓰면 어떤 식일까?","식":["작은 수를 $x$, 큰 수를 $y$ 라 하면","합이 45: $x+y=45$","3배에서 뺌: $3x-y=3$"],"설명":"빼지는 수가 작은 수의 3배이고 빼는 수가 큰 수이다. 순서가 바뀌면 식이 달라진다.","확인":null,"스킬":"C7"},{"제목":"두 식을 더해 작은 수 구하기","힌트":"$y$ 의 계수가 서로 반대이므로 더하면 무엇이 남을까?","식":["$(x+y)+(3x-y)=45+3$","$4x=48$, $x=12$"],"설명":"$y$ 의 계수가 $1$ 과 $-1$ 이므로 더하면 $y$ 가 사라진다.","확인":"12","스킬":"A10"},{"제목":"큰 수 구하고 두 조건 확인","힌트":"$x=12$ 를 $x+y=45$ 에 넣으면 $y$ 는 얼마일까?","식":["$12+y=45$, $y=33$","$3\\times12-33=3$ 으로 조건을 만족"],"설명":"구한 두 수를 문장의 두 조건에 넣어 확인한다. 작은 수가 12, 큰 수가 33이다.","확인":null,"스킬":"A10"}]},"tb-비상중2-p082-1-2":{"길":"x 에 자연수를 차례로 넣어 y 가 x 마다 하나로 정해지는지 본다","단계":[{"제목":"x 값마다 최대공약수 구하기","힌트":"$x=1,2,3,\\cdots$ 일 때 $x$ 와 8 의 최대공약수는 각각 얼마일까?","식":["$x=1,2,3,4,5,6$ 일 때","$y=1,2,1,4,1,2$"],"설명":"각 $x$ 와 8 의 최대공약수를 하나씩 구해 표로 정리한다.","확인":null,"스킬":"P4"},{"제목":"함수의 정의와 비교","고비":true,"힌트":"$x$ 의 값 하나에 $y$ 의 값이 몇 개씩 정해질까?","식":["최대공약수는 두 수에 대해 오직 하나로 정해진다","$x$ 하나에 $y$ 하나가 대응하므로 함수이다"],"설명":"함수는 $x$ 의 값 하나에 $y$ 의 값이 오직 하나씩 정해지는 대응이다. $y$ 의 값이 같은 $x$ 가 여럿이어도 함수이다.","확인":null,"스킬":"P4"}]},"tb-비상중2-p082-2":{"길":"선지마다 x 의 값 하나에 y 가 하나로 정해지는지 따진다","단계":[{"제목":"함수인 선지를 식으로 나타내기","힌트":"①, ③, ④, ⑤ 에서 $x$ 를 정하면 $y$ 는 몇 개일까?","식":["① $y=x+1$, ③ $xy=20$ 에서 $y=\\frac{20}{x}$","④ $y=20x$, ⑤ $y=30-x$"],"설명":"네 선지 모두 $x$ 의 값을 정하면 $y$ 의 값이 하나로 정해진다.","확인":null,"스킬":"C7"},{"제목":"②의 대응 확인하기","고비":true,"힌트":"$x=1$ 과 $x=4$ 일 때 조건에 맞는 소수 $y$ 는 각각 몇 개일까?","식":["$x=1$: 1보다 작은 소수는 없다","$x=4$: 4보다 작은 소수는 $2,3$"],"설명":"$y$ 가 없거나 둘 이상이면 함수가 아니다. 따라서 함수가 아닌 것은 ② 이다.","확인":null,"스킬":"C7"}]},"tb-비상중2-p082-3":{"길":"x 자리에 각 값을 넣어 함숫값을 계산하고 맞지 않는 선지를 찾는다","단계":[{"제목":"①, ② 의 함숫값 계산","고비":true,"힌트":"$x$ 자리에 $-2$ 를 넣으면 $-\\frac{1}{2}x$ 는 얼마가 될까?","식":["① $f(-12)=-\\frac{1}{2}\\times(-12)=6$","② $f(-2)=-\\frac{1}{2}\\times(-2)=1$"],"설명":"$f(x)$ 의 $x$ 자리에 값을 넣어 $-\\frac{1}{2}$ 에 곱한다. ② 는 선지의 $\\frac{1}{4}$ 과 다르다.","확인":null,"스킬":"C6"},{"제목":"③, ④, ⑤ 의 함숫값 계산","힌트":"나머지 선지의 함숫값은 선지와 같을까?","식":["③ $f(0)=0$","④ $f(1)=-\\frac{1}{2}$","⑤ $f(6)=-\\frac{1}{2}\\times6=-3$"],"설명":"③, ④, ⑤ 는 선지와 같다. 옳지 않은 것은 ② 이다.","확인":null,"스킬":"C6"}]},"tb-비상중2-p082-4":{"길":"f 와 g 의 값을 각각 구한 뒤 빼는 부호에 주의해 계산한다","단계":[{"제목":"f 의 함숫값 구하기","힌트":"$12x$ 의 $x$ 자리에 $-\\frac{1}{2}$ 을 넣으면 얼마일까?","식":["$f\\left(-\\frac{1}{2}\\right)=12\\times\\left(-\\frac{1}{2}\\right)=-6$"],"설명":"분수를 괄호로 묶어 대입하고 12에 곱한다.","확인":"-6","스킬":"C6"},{"제목":"g 의 함숫값 구하기","힌트":"$x-3$ 의 $x$ 자리에 1을 넣으면 얼마일까?","식":["$g(1)=1-3=-2$"],"설명":"$g(x)=x-3$ 에 $x=1$ 을 대입한다.","확인":"-2","스킬":"C6"},{"제목":"음수를 빼는 계산","고비":true,"힌트":"$-2$ 를 빼는 것은 어떤 계산과 같을까?","식":["$f\\left(-\\frac{1}{2}\\right)-g(1)=-6-(-2)$","$=-6+2=-4$"],"설명":"음수를 빼면 그 수의 절댓값을 더하는 것과 같다.","확인":"-4","스킬":"C6"}]},"tb-비상중2-p082-5":{"길":"f(k) 의 식을 k 에 대한 방정식으로 보고 푼다","단계":[{"제목":"함숫값 조건을 방정식으로 쓰기","힌트":"$f(x)$ 의 $x$ 자리에 $k$ 를 넣으면 어떤 방정식이 될까?","식":["$f(k)=-\\frac{3}{2}k$","$-\\frac{3}{2}k=-6$"],"설명":"함숫값이 $-6$ 이므로 $k$ 에 대한 일차방정식이 된다.","확인":null,"스킬":"C6"},{"제목":"k 의 값 구하기","고비":true,"힌트":"양변에 $-\\frac{3}{2}$ 의 역수를 곱하면 $k$ 는 얼마일까?","식":["$k=-6\\times\\left(-\\frac{2}{3}\\right)$","$k=4$"],"설명":"계수가 분수이면 역수를 양변에 곱한다. 음수끼리 곱하면 양수이다.","확인":"4","스킬":"C6"}]},"tb-비상중2-p082-6":{"길":"f(-2)=4 로 a 를 먼저 구하고 f(x) 에 6 을 넣는다","단계":[{"제목":"a 의 값 구하기","고비":true,"힌트":"$x$ 자리에 $-2$ 를 넣으면 $a$ 에 대한 어떤 식이 될까?","식":["$\\frac{a}{-2}=4$","$a=4\\times(-2)=-8$"],"설명":"양변에 $-2$ 를 곱해 $a$ 를 구한다. 분모의 부호에 주의한다.","확인":"-8","스킬":"C6"},{"제목":"f(6) 의 값 구하기","힌트":"$f(x)=\\frac{-8}{x}$ 의 $x$ 자리에 6을 넣으면 얼마일까?","식":["$f(6)=\\frac{-8}{6}$","$=-\\frac{4}{3}$"],"설명":"약분해 기약분수로 나타낸다.","확인":"-4/3","스킬":"C6"}]},"tb-비상중2-p083-1":{"길":"식을 y=ax+b 꼴로 정리해 x 의 차수와 계수 a 가 0 이 아닌지 따진다","단계":[{"제목":"식을 정리해 y=ax+b 꼴로 만들기","고비":true,"힌트":"정리하고 나면 $x$ 의 계수는 어떻게 될까?","식":["② $y=\\frac{-5x+1}{2}=-\\frac{5}{2}x+\\frac{1}{2}$","④ $y=x+(4-x)=4$"],"설명":"일차함수는 정리했을 때 $y=ax+b$ ($a\\ne0$) 꼴이다. ④ 는 $x$ 항이 지워져 상수가 되므로 일차함수가 아니다.","확인":null,"스킬":"G9"},{"제목":"차수와 분모 확인하기","힌트":"$x^{2}$ 이 남거나 $x$ 가 분모에 있는 식은 일차함수일까?","식":["① $y=x^{2}+2$ 는 이차식","③ $y=\\frac{1}{x}$ 은 $x$ 가 분모에 있음","⑤ $y=x^{2}-3x$ 는 이차식"],"설명":"①, ⑤ 는 $x^{2}$ 이 있고 ③ 은 $x$ 가 분모에 있어 모두 일차함수가 아니다. 일차함수는 ② 이다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p083-2":{"길":"y축 방향 평행이동은 상수항에만 더하므로 식을 비교해 a, b 를 구한다","단계":[{"제목":"평행이동한 식 쓰기","고비":true,"힌트":"$y$ 축 방향으로 $b$ 만큼 옮기면 식의 어느 부분이 달라질까?","식":["$y=-2x-3+b$"],"설명":"$y$ 축 방향 평행이동은 기울기는 그대로 두고 상수항에만 $b$ 를 더한다.","확인":null,"스킬":"G4"},{"제목":"계수를 비교해 a, b 구하기","힌트":"$y=ax+7$ 과 기울기, 상수항을 각각 비교하면 $b$ 는 얼마일까?","식":["$a=-2$","$-3+b=7$, $b=10$"],"설명":"두 식이 같으므로 $x$ 의 계수끼리, 상수항끼리 같다.","확인":"10","스킬":"G4"},{"제목":"a+b 계산하기","힌트":"구한 $a$, $b$ 를 더하면 얼마일까?","식":["$a+b=-2+10=8$"],"설명":"$a=-2$ 와 $b=10$ 을 더한다.","확인":"8","스킬":"G4"}]},"tb-비상중2-p083-3":{"길":"각 식에 y=0 을 넣어 x절편을 구하고 다른 하나를 찾는다","단계":[{"제목":"①, ② 의 x절편 구하기","힌트":"$x$ 절편은 $y$ 의 값이 얼마일 때의 $x$ 값일까?","식":["① $0=-2x+4$, $x=2$","② $0=-x+2$, $x=2$"],"설명":"$x$ 절편은 그래프가 $x$ 축과 만나는 점이므로 $y=0$ 을 대입해 구한다.","확인":"2","스킬":"G9"},{"제목":"③, ④, ⑤ 의 x절편 구하기","고비":true,"힌트":"세 식의 $x$ 절편 중 앞의 값과 다른 것은 어느 것일까?","식":["③ $0=\\frac{1}{2}x-1$, $x=2$","④ $0=x-2$, $x=2$","⑤ $0=3x+6$, $x=-2$"],"설명":"①~④ 의 $x$ 절편은 모두 같고 ⑤ 만 다르다. $x$ 절편이 다른 것은 ⑤ 이다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p083-4":{"길":"x절편을 점 (-3, 0) 으로 보고 대입해 k 를 구하면 그것이 y절편이다","단계":[{"제목":"x절편을 점의 좌표로 바꿔 대입","고비":true,"힌트":"$x$ 절편이 $-3$ 이면 그래프는 어떤 좌표의 점을 지날까?","식":["$x$ 절편이 $-3$ 이므로 점 $(-3,\\ 0)$ 을 지난다","$0=\\frac{5}{6}\\times(-3)+k=-\\frac{5}{2}+k$"],"설명":"$x$ 절편은 $y=0$ 인 점의 $x$ 좌표이다. 이 점의 좌표를 식에 넣으면 $k$ 에 대한 방정식이 된다.","확인":null,"스킬":"G9"},{"제목":"k 를 구해 y절편 읽기","힌트":"$y$ 절편은 $x=0$ 일 때의 $y$ 값이므로 식에서 어떤 수와 같을까?","식":["$k=\\frac{5}{2}$","$x=0$ 일 때 $y=k$ 이므로 $y$ 절편은 $k$ 와 같다"],"설명":"$y=\\frac{5}{6}x+k$ 에서 $x=0$ 을 넣으면 $y=k$ 이다. 따라서 구한 $k$ 가 곧 $y$ 절편이다.","확인":"5/2","스킬":"G9"}]},"tb-비상중2-p083-5":{"길":"두 점의 좌표로 기울기 식을 같은 순서로 세워 k 에 대해 푼다","단계":[{"제목":"기울기 식 세우기","고비":true,"힌트":"$y$ 의 증가량과 $x$ 의 증가량을 같은 점의 순서로 빼면 어떤 식이 될까?","식":["$y$ 의 증가량 $-4-k$, $x$ 의 증가량 $2-(-1)$","$\\frac{-4-k}{2-(-1)}=\\frac{-4-k}{3}=-3$"],"설명":"기울기는 $y$ 의 증가량을 $x$ 의 증가량으로 나눈 값이다. 두 점의 빼는 순서를 분자와 분모에서 똑같이 한다.","확인":null,"스킬":"G9"},{"제목":"k 의 값 구하기","힌트":"양변에 3을 곱한 뒤 $k$ 를 정리하면 얼마일까?","식":["$-4-k=-9$","$k=5$"],"설명":"분모를 없애도록 양변에 3을 곱한다. $-4$ 를 이항한 뒤 부호를 바꿔 $k$ 를 구한다.","확인":"5","스킬":"G9"}]},"tb-비상중2-p083-6":{"길":"x절편과 y절편을 구해 두 점을 지나는 직선이 그려진 선지를 찾는다","단계":[{"제목":"x절편 구하기","고비":true,"힌트":"$y=0$ 을 넣으면 $x$ 는 얼마일까?","식":["$0=-\\frac{2}{3}x+2$","$\\frac{2}{3}x=2$, $x=3$"],"설명":"$x$ 절편은 $y=0$ 일 때의 $x$ 값이다. 계수가 분수이므로 양변에 $\\frac{3}{2}$ 을 곱한다.","확인":"3","스킬":"G9"},{"제목":"두 절편을 지나는 직선 찾기","힌트":"$x=0$ 일 때 $y$ 는 얼마이고, 두 절편의 좌표는 각각 무엇일까?","식":["$x=0$ 일 때 $y=2$ 이므로 $y$ 절편은 $2$","두 점 $(3,\\ 0)$, $(0,\\ 2)$ 를 지나는 직선"],"설명":"직선은 두 점으로 정해지므로 $x$ 축 위의 점과 $y$ 축 위의 점을 지나는 직선이 그려진 선지를 찾는다. 그 선지는 ④ 이다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p084-1":{"길":"식에서 점, 절편, 기울기의 부호를 하나씩 확인해 옳지 않은 설명을 찾는다","단계":[{"제목":"점과 절편 확인하기","힌트":"$x=3$ 을 넣은 $y$ 값과 $y=0$ 을 넣은 $x$ 값은 각각 얼마일까?","식":["① $x=3$ 일 때 $y=\\frac{4}{3}\\times3-2=2$ 이므로 점 $(3,\\ 2)$ 를 지난다","② $y=0$ 이면 $x=\\frac{3}{2}$, $x=0$ 이면 $y=-2$"],"설명":"①, ② 는 선지의 설명과 같다.","확인":null,"스킬":"G9"},{"제목":"y절편과 지나는 사분면 확인하기","힌트":"$y$ 절편의 부호와 기울기의 부호로 지나는 사분면을 정하면 어떻게 될까?","식":["③ $y$ 절편 $-2<0$ 이므로 $y$ 축의 음의 부분에서 만난다","⑤ 기울기 $>0$, $y$ 절편 $<0$ 이므로 제2사분면을 지나지 않는다"],"설명":"③, ⑤ 도 선지의 설명과 같다.","확인":null,"스킬":"G9"},{"제목":"기울기의 부호로 방향 확인","고비":true,"힌트":"기울기가 양수이면 직선은 오른쪽 위와 아래 중 어느 쪽으로 향할까?","식":["기울기 $\\frac{4}{3}>0$ 이므로 오른쪽 위로 향하는 직선","④ 는 옳지 않은 설명"],"설명":"기울기가 양수이면 $x$ 가 커질 때 $y$ 도 커지므로 오른쪽 위로 향한다. 옳지 않은 것은 ④ 이다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p084-2":{"길":"평행은 기울기가 같고 y절편이 다르다는 조건으로 a, b 를 정한다","단계":[{"제목":"기울기로 a 정하기","힌트":"두 직선이 평행하면 기울기는 어떤 관계일까?","식":["$y=ax+6$ 의 기울기 $a$, $y=-3x+b$ 의 기울기 $-3$","$a=-3$"],"설명":"평행한 두 직선은 기울기가 같다.","확인":null,"스킬":"G9"},{"제목":"y절편으로 b 의 조건 정하기","고비":true,"힌트":"$y$ 절편까지 같으면 두 직선은 평행일까, 일치할까?","식":["$y$ 절편은 $6$ 과 $b$","$b\\ne6$"],"설명":"$y$ 절편까지 같으면 두 직선이 완전히 겹쳐 일치한다. 평행이려면 $y$ 절편은 달라야 한다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p084-3":{"길":"증가량으로 기울기를 구해 직선의 식을 세우고 점의 좌표를 대입한다","단계":[{"제목":"기울기와 직선의 식 구하기","고비":true,"힌트":"$y$ 의 값이 감소하면 $y$ 의 증가량의 부호는 어떻게 될까?","식":["$y$ 의 증가량 $-2$, $x$ 의 증가량 $6$","기울기 $=\\frac{-2}{6}=-\\frac{1}{3}$","$y$ 절편이 $4$ 이므로 $y=-\\frac{1}{3}x+4$"],"설명":"감소는 증가량이 음수라는 뜻이다. 기울기와 $y$ 절편을 알면 직선의 식이 정해진다.","확인":"-1/3","스킬":"G9"},{"제목":"점의 좌표를 대입해 k 구하기","힌트":"점 $(k,\\ 5)$ 의 $x$ 좌표와 $y$ 좌표를 식에 넣으면 어떤 방정식이 될까?","식":["$5=-\\frac{1}{3}k+4$","$-\\frac{1}{3}k=1$, $k=-3$"],"설명":"직선 위의 점이므로 좌표를 식에 대입한다. 양변에 $-3$ 을 곱해 $k$ 를 구한다.","확인":"-3","스킬":"G9"}]},"tb-비상중2-p084-4":{"길":"그래프에서 눈금에 맞는 두 점을 읽어 기울기와 y절편을 구한다","단계":[{"제목":"그래프에서 두 점 읽기","힌트":"그래프 위에서 좌표를 정확히 읽을 수 있는 두 점은 어디일까?","식":["두 점 $(-4,\\ 2)$, $(1,\\ -3)$"],"설명":"점선이 눈금과 만나는 두 점은 좌표가 확실하다. 이 두 점을 지나는 직선이다.","확인":null,"스킬":"G9"},{"제목":"기울기 a 구하기","고비":true,"힌트":"두 점의 $y$ 좌표의 차를 $x$ 좌표의 차로 나누되 같은 순서로 빼면 얼마일까?","식":["$a=\\frac{-3-2}{1-(-4)}=\\frac{-5}{5}$","$a=-1$"],"설명":"분자와 분모에서 두 점을 같은 순서로 뺀다. 그래프가 오른쪽 아래로 향하므로 기울기는 음수이다.","확인":"-1","스킬":"G9"},{"제목":"y절편 b 구하기","힌트":"$a=-1$ 이고 점 $(1,\\ -3)$ 을 지나므로 식에 넣으면 $b$ 는 얼마일까?","식":["$-3=-1\\times1+b$","$b=-2$"],"설명":"한 점의 좌표를 $y=-x+b$ 에 대입해 $b$ 를 구한다.","확인":"-2","스킬":"G9"},{"제목":"a-b 의 값 구하기","힌트":"$-2$ 를 빼는 계산은 어떻게 바뀔까?","식":["$a-b=-1-(-2)=-1+2=1$"],"설명":"음수를 빼면 그 수의 절댓값을 더하는 것과 같다.","확인":"1","스킬":"G9"}]},"tb-비상중2-p084-5":{"길":"한 단위당 늘어나는 길이를 구해 길이의 관계식을 세운다","단계":[{"제목":"1 g당 늘어나는 길이 구하기","힌트":"10 g에 2 cm 늘어나면 1 g에는 몇 cm 늘어날까?","식":["$2\\div10=0.2$"],"설명":"무게에 비례해 늘어나므로 늘어난 길이를 무게로 나누면 1 g당 늘어나는 길이가 된다.","확인":"0.2","스킬":"C7"},{"제목":"무게와 용수철 길이의 관계식 세우기","고비":true,"힌트":"처음 길이에 늘어난 길이를 더하면 용수철의 길이는 어떤 식이 될까?","식":["무게 $x\\,\\mathrm{g}$, 용수철의 길이 $y\\,\\mathrm{cm}$","$y=0.2x+25$"],"설명":"처음 길이 25 cm에 무게 $x$에 비례해 늘어난 길이 $0.2x$를 더한 식이다.","확인":null,"스킬":"C7"},{"제목":"무게가 25 g일 때의 길이 구하기","힌트":"$x$에 25를 넣으면 $y$는 얼마가 될까?","식":["$y=0.2\\times25+25$","$y=30$"],"설명":"구한 식에 $x=25$를 대입하면 용수철의 길이가 나온다. 선지 중 같은 값은 ②이다.","확인":"30","스킬":"C7"}]},"tb-비상중2-p084-6":{"길":"그래프의 두 점으로 관계식을 구하고 남은 양이 400일 때 x를 구한다","단계":[{"제목":"그래프에서 두 점 읽기","힌트":"그래프가 $y$축과 $x$축에 닿는 점의 좌표는 각각 무엇일까?","식":["$(0,\\ 1000)$, $(250,\\ 0)$"],"설명":"처음에는 수액이 1000 mL이고, 250분 후에는 남은 양이 0이 된다.","확인":null,"스킬":"C7"},{"제목":"기울기와 관계식 구하기","고비":true,"힌트":"$x$가 1 늘어날 때 $y$는 얼마나 변할까?","식":["기울기 $\\frac{0-1000}{250-0}=-4$","$y=-4x+1000$"],"설명":"기울기는 $y$의 증가량을 $x$의 증가량으로 나눈 값이고, $y$절편이 1000이므로 $y=-4x+1000$이다.","확인":"-4","스킬":"C7"},{"제목":"남은 수액이 400 mL일 때 x 구하기","힌트":"$y=400$을 식에 넣으면 $x$에 대한 어떤 방정식이 될까?","식":["$400=-4x+1000$","$4x=600$, $x=150$"],"설명":"관계식의 $y$에 400을 대입해 $x$를 구하면 수액을 맞기 시작한 지 150분 후이다.","확인":"150","스킬":"C7"}]},"tb-비상중2-p085-1":{"길":"y에 대하여 풀어 두 절편의 부호를 읽고 그래프를 고른다","단계":[{"제목":"y에 대하여 풀기","힌트":"$2x$와 4를 우변으로 옮기면 $y$는 어떤 식이 될까?","식":["$y=-2x-4$"],"설명":"기울기는 $-2$, $y$절편은 $-4$이다.","확인":null,"스킬":"G9"},{"제목":"x절편 구하기","힌트":"$y=0$을 넣으면 $x$는 얼마일까?","식":["$2x+0+4=0$","$x=-2$"],"설명":"$x$절편은 $y=0$일 때의 $x$의 값이다. $y$절편은 $-4$이므로 두 절편이 모두 음수이다.","확인":"-2","스킬":"G9"},{"제목":"두 절편의 부호로 그래프 고르기","고비":true,"힌트":"두 절편이 모두 음수인 직선은 원점의 어느 쪽을 지날까?","식":["$(-2,\\ 0)$, $(0,\\ -4)$를 지난다","두 절편이 모두 음수인 직선 $\\to$ ⑤"],"설명":"$x$축과 $y$축의 음의 부분에서 각각 만나는 직선을 고른다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p085-2":{"길":"y에 대하여 풀어 기울기와 절편을 읽고 선지를 하나씩 확인한다","단계":[{"제목":"y=ax+b 꼴로 바꾸기","힌트":"$5x$와 4를 우변으로 옮긴 뒤 양변을 $-2$로 나누면 어떤 식이 될까?","식":["$-2y=-5x-4$","$y=\\frac{5}{2}x+2$"],"설명":"$y$에 대하여 풀면 기울기와 $y$절편이 바로 보인다.","확인":null,"스킬":"G9"},{"제목":"점 (-2, 3)을 지나는지 확인하기","고비":true,"힌트":"$x=-2$를 넣었을 때 $y$는 얼마가 될까?","식":["$y=\\frac{5}{2}\\times(-2)+2=-3$","$-3\\ne3$"],"설명":"$x=-2$일 때 $y=-3$이므로 점 $(-2,\\ 3)$은 직선 위의 점이 아니다. ③이 옳지 않다.","확인":"-3","스킬":"G9"},{"제목":"나머지 선지 확인하기","힌트":"기울기와 $y$절편의 부호로 직선이 지나는 사분면을 정하면 어떻게 될까?","식":["① $x$절편 $-\\frac{4}{5}$, ② $y$절편 $2$, ④ 기울기 $\\frac{5}{2}$ 모두 옳다","기울기와 $y$절편이 모두 양수이므로 제4사분면을 지나지 않는다 $\\to$ ⑤ 옳다"],"설명":"$x$절편은 $y=0$을 넣어 구한다. 오른쪽 위로 향하고 $y$절편이 양수인 직선은 제1, 2, 3사분면을 지난다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p085-3":{"길":"y에 대하여 풀어 기울기와 y절편을 주어진 조건과 비교한다","단계":[{"제목":"y에 대하여 풀어 기울기·절편 읽기","고비":true,"힌트":"$3y$만 좌변에 남기고 나머지를 옮기면 부호는 어떻게 될까?","식":["$3y=-ax-b$","$y=-\\frac{a}{3}x-\\frac{b}{3}$"],"설명":"이항하면 $a$, $b$ 앞에 마이너스가 붙는다. 기울기는 $-\\frac{a}{3}$, $y$절편은 $-\\frac{b}{3}$이다.","확인":null,"스킬":"G9"},{"제목":"평행 조건으로 a 구하기","힌트":"평행한 두 직선은 기울기가 같다. 기울기가 $-4$가 되려면 $a$는 얼마일까?","식":["$-\\frac{a}{3}=-4$","$a=12$"],"설명":"평행한 두 직선은 기울기가 같으므로 $-\\frac{a}{3}$을 $-4$와 같게 놓고 양변에 $-3$을 곱한다.","확인":"12","스킬":"G9"},{"제목":"y절편 조건으로 b 구하기","힌트":"$y$절편 $-\\frac{b}{3}$이 $\\frac{1}{3}$이 되려면 $b$는 얼마일까?","식":["$-\\frac{b}{3}=\\frac{1}{3}$","$b=-1$"],"설명":"양변에 $-3$을 곱하면 $b=-1$이다.","확인":"-1","스킬":"G9"},{"제목":"a+b 계산하기","힌트":"구한 $a$와 $b$를 더하면?","식":["$a+b=12+(-1)=11$"],"설명":"$b$가 음수이므로 12에서 1을 뺀 값이다.","확인":"11","스킬":"G9"}]},"tb-비상중2-p085-4":{"길":"x축에 수직인 직선은 x=(수) 꼴임을 이용해 선지를 정리한다","단계":[{"제목":"x축에 수직인 직선의 꼴 알기","고비":true,"힌트":"$x$축에 수직이면 직선 위의 모든 점에서 어느 좌표가 같을까?","식":["$x$축에 수직 $\\to$ $x$좌표가 일정 $\\to$ $x=(\\text{수})$ 꼴"],"설명":"$x$축에 수직인 직선은 세로선이므로 $x$좌표가 모두 같고, 식에 $y$가 나타나지 않는다.","확인":null,"스킬":"G9"},{"제목":"각 선지를 x=(수) 또는 y=(수) 꼴로 정리하기","힌트":"$-3x=-4$를 $x$에 대하여 풀면 어떤 값이 될까?","식":["① $y=1$, ③ $y=-\\frac{3}{5}$, ⑤ $y=0$ 은 $y=(\\text{수})$ 꼴","② $x=-\\frac{1}{2}$ 은 그대로 $x=(\\text{수})$ 꼴","④ $-3x=-4$ 에서 $x=\\frac{4}{3}$"],"설명":"$5y=-3$, $6y=0$은 $y$에 대해 정리되는 가로선이다. $-3x=-4$는 양변을 $-3$으로 나누면 $x=\\frac{4}{3}$이다.","확인":"4/3","스킬":"G9"},{"제목":"x=(수) 꼴인 선지 고르기","힌트":"$x=(\\text{수})$ 꼴로 정리된 선지의 번호는 무엇일까?","식":["$x=(\\text{수})$ 꼴은 ②, ④"],"설명":"세로선인 ②와 ④가 $x$축에 수직인 직선이다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p085-5":{"길":"y축에 평행한 직선은 x좌표가 일정함을 이용해 식을 정한다","단계":[{"제목":"y축에 평행한 직선의 꼴 알기","고비":true,"힌트":"$y$축에 평행한 직선 위의 점들은 어느 좌표가 모두 같을까?","식":["$y$축에 평행 $\\to$ $x$좌표가 일정 $\\to$ $x=(\\text{수})$ 꼴"],"설명":"$y$축에 평행한 직선은 세로선이므로 직선 위의 모든 점의 $x$좌표가 같다.","확인":null,"스킬":"G9"},{"제목":"지나는 점으로 직선의 식 정하기","힌트":"점 $(3,\\ -9)$에서 직선의 식을 정하는 것은 어느 좌표일까?","식":["점 $(3,\\ -9)$의 $x$좌표는 $3$","$x=3$"],"설명":"직선이 $x$좌표 3인 점을 지나므로 $x=3$이다. 선지 중 같은 식은 ②이다. ④ $3x=-9$는 $x=-3$이다.","확인":null,"스킬":"G9"}]},"tb-비상중2-p085-6":{"길":"y축에 수직이면 두 점의 y좌표가 같다고 놓고 방정식을 푼다","단계":[{"제목":"y축에 수직인 직선의 조건 세우기","고비":true,"힌트":"$y$축에 수직이면 직선 위의 두 점에서 어느 좌표가 같을까?","식":["$y$축에 수직 $\\to$ $y$좌표가 같다","$-k+1=2k+4$"],"설명":"$y$축에 수직인 직선은 가로선이므로 두 점의 $y$좌표가 같다.","확인":null,"스킬":"G9"},{"제목":"방정식을 풀어 k 구하기","힌트":"$k$를 포함한 항은 한쪽으로, 수는 반대쪽으로 옮기면?","식":["$-k-2k=4-1$","$-3k=3$, $k=-1$"],"설명":"이항해 정리한 뒤 양변을 $-3$으로 나눈다.","확인":"-1","스킬":"G9"}]},"tb-비상중2-p086-1":{"길":"두 식의 절편으로 그림의 직선을 찾아 두 직선의 교점을 고른다","단계":[{"제목":"x+y=1의 직선 찾기","힌트":"$x=0$, $y=0$을 각각 넣으면 두 절편은 얼마일까?","식":["$x+y=1$에서 $x$절편 $1$, $y$절편 $1$","두 절편이 모두 $1$인 직선은 $n$"],"설명":"그림에서 $x$축과 $y$축에 모두 1에서 만나는 직선은 $n$이다.","확인":null,"스킬":"G1"},{"제목":"2x-y=-3의 직선 찾기","힌트":"$x=0$을 넣으면 $y$는 얼마일까?","식":["$y=2x+3$","$y$절편 $3$, $x$절편 $-\\frac{3}{2}$인 직선은 $l$"],"설명":"$y$에 대하여 풀면 $y$절편은 3이고, $y=0$일 때 $x=-\\frac{3}{2}$이다. 그림에서 이 두 절편을 가진 직선은 $l$이다.","확인":"3","스킬":"G1"},{"제목":"두 직선의 교점 찾기","고비":true,"힌트":"연립방정식의 해는 그래프에서 어떤 점일까?","식":["연립방정식의 해 $=$ 두 직선 $l$, $n$의 교점","$l$과 $n$이 만나는 점은 $\\mathrm{B}$"],"설명":"두 일차방정식의 그래프가 만나는 점의 좌표가 연립방정식의 해이다.","확인":null,"스킬":"G1"}]},"tb-비상중2-p086-2":{"길":"한 식을 y= 꼴로 만들어 다른 식에 대입해 교점을 구한다","단계":[{"제목":"대입할 수 있게 y를 x로 나타내기","힌트":"$2x-y=0$을 $y$에 대하여 풀면 어떤 식이 될까?","식":["$y=2x$"],"설명":"교점의 좌표는 두 식을 동시에 만족하므로 연립방정식의 해이다.","확인":null,"스킬":"G1"},{"제목":"대입하여 x 구하기","고비":true,"힌트":"$x+2y=10$의 $y$ 자리에 $2x$를 넣으면 어떤 방정식이 될까?","식":["$x+2(2x)=10$","$5x=10$, $x=2$"],"설명":"$y$를 $2x$로 바꾸면 미지수가 $x$ 하나인 방정식이 된다.","확인":"2","스킬":"A10"},{"제목":"교점의 좌표와 ab 구하기","힌트":"$y=2x$에 $x=2$를 넣고 $a$, $b$를 곱하면?","식":["$y=2\\times2=4$","$(a,\\ b)=(2,\\ 4)$, $ab=8$"],"설명":"교점이 $(a,\\ b)$이므로 $a=2$, $b=4$이다.","확인":"8","스킬":"G1"}]},"tb-비상중2-p086-3":{"길":"그래프의 교점 좌표를 두 방정식에 각각 대입해 a, b를 구한다","단계":[{"제목":"그래프에서 교점의 좌표 읽기","힌트":"두 직선이 만나는 점에서 점선을 따라 $x$좌표와 $y$좌표를 읽으면?","식":["교점 $(1,\\ -3)$"],"설명":"연립방정식의 해는 두 그래프의 교점의 좌표이므로 $x=1$, $y=-3$을 두 식에 모두 대입할 수 있다.","확인":null,"스킬":"G1"},{"제목":"첫째 식에 대입하여 a 구하기","힌트":"$ax+y=-1$에 $x=1$, $y=-3$을 넣으면 $a$에 대한 어떤 식이 될까?","식":["$a\\times1+(-3)=-1$","$a=2$"],"설명":"$a-3=-1$이므로 $a=2$이다.","확인":"2","스킬":"G1"},{"제목":"둘째 식에 대입하여 b 구하기","고비":true,"힌트":"$3x-2y=b$에 $x=1$, $y=-3$을 넣으면 $b$는 얼마일까?","식":["$3\\times1-2\\times(-3)=b$","$b=9$"],"설명":"$-2$에 음수 $-3$을 곱하면 양수 $+6$이 되므로 $3+6=9$이다.","확인":"9","스킬":"G1"},{"제목":"a+b 계산하기","힌트":"구한 $a$와 $b$를 더하면?","식":["$a+b=2+9=11$"],"설명":"선지 중 11은 ④이다.","확인":"11","스킬":"G1"}]},"tb-비상중2-p086-4":{"길":"연립방정식으로 교점을 구한 뒤 x축에 수직이면 x좌표만 쓴다","단계":[{"제목":"두 식을 빼서 x 구하기","힌트":"두 식에서 $y$의 계수가 같다. 변끼리 빼면 $x$에 대한 어떤 식이 될까?","식":["$(x-y)-(3x-y)=-2-(-8)$","$-2x=6$, $x=-3$"],"설명":"$y$의 계수가 같으므로 두 식을 변끼리 빼면 $y$가 사라진다.","확인":"-3","스킬":"G1"},{"제목":"교점의 y좌표 구하기","힌트":"$x=-3$을 $x-y=-2$에 넣으면 $y$는 얼마일까?","식":["$-3-y=-2$","$y=-1$, 교점 $(-3,\\ -1)$"],"설명":"구한 $x$를 한 식에 대입해 $y$를 구한다.","확인":"-1","스킬":"G1"},{"제목":"x축에 수직인 직선의 식 쓰기","고비":true,"힌트":"$x$축에 수직인 직선은 교점의 어느 좌표만 식에 쓸까?","식":["$x$축에 수직 $\\to$ $x=(\\text{수})$ 꼴","교점의 $x$좌표가 $-3$이므로 $x=-3$"],"설명":"$x$축에 수직인 직선은 세로선이므로 $x$좌표가 일정하다. $y$좌표 $-1$은 식에 쓰지 않는다.","확인":null,"스킬":"G1"}]},"tb-비상중2-p086-5":{"길":"해가 무수히 많으면 두 식이 같으므로 한 식에 수를 곱해 계수를 비교한다","단계":[{"제목":"상수항을 같게 만드는 수 찾기","고비":true,"힌트":"$x+by=-1$의 우변 $-1$을 첫째 식의 우변 4로 만들려면 양변에 무엇을 곱할까?","식":["해가 무수히 많다 $\\to$ 두 식이 같은 직선","$x+by=-1$의 양변에 $-4$를 곱하면 $-4x-4by=4$"],"설명":"해가 무수히 많으면 한 식에 적당한 수를 곱해 다른 식과 완전히 같게 만들 수 있다.","확인":"-4","스킬":"G1"},{"제목":"계수를 비교하여 a, b 구하기","힌트":"$ax-y=4$와 $-4x-4by=4$에서 $x$의 계수끼리, $y$의 계수끼리 같게 놓으면?","식":["$a=-4$","$-1=-4b$, $b=\\frac{1}{4}$"],"설명":"두 식이 같으려면 $x$의 계수, $y$의 계수, 상수항이 각각 같아야 한다.","확인":"1/4","스킬":"G1"},{"제목":"a+b 계산하기","힌트":"$-4$와 $\\frac{1}{4}$을 더하면?","식":["$a+b=-4+\\frac{1}{4}=-\\frac{15}{4}$"],"설명":"$-4=-\\frac{16}{4}$으로 통분해 더한다. 선지 중 $-\\frac{15}{4}$는 ②이다.","확인":"-15/4","스킬":"G1"}]},"tb-비상중2-p086-6":{"길":"교점이 없으면 두 직선이 평행이므로 두 식의 기울기를 같게 놓는다","단계":[{"제목":"교점이 없을 조건 알기","고비":true,"힌트":"교점이 없는 두 직선은 기울기와 $y$절편이 각각 어떤 관계일까?","식":["교점이 없다 $\\to$ 두 직선이 평행","기울기는 같고 $y$절편은 다르다"],"설명":"기울기가 다르면 두 직선은 반드시 한 점에서 만난다. 기울기가 같고 $y$절편이 같으면 겹쳐서 교점이 무수히 많다.","확인":null,"스킬":"G1"},{"제목":"y에 대하여 풀어 기울기와 y절편 읽기","힌트":"두 식을 각각 $y=ax+b$ 꼴로 바꾸면?","식":["$y=-\\frac{k}{2}x+\\frac{5}{2}$","$y=2x+4$"],"설명":"기울기는 각각 $-\\frac{k}{2}$, $2$이고 $y$절편은 각각 $\\frac{5}{2}$, $4$이다.","확인":null,"스킬":"G1"},{"제목":"기울기를 같게 놓아 k 구하기","힌트":"$-\\frac{k}{2}=2$를 풀면 $k$는 얼마일까?","식":["$-\\frac{k}{2}=2$","$k=-4$"],"설명":"양변에 $-2$를 곱한다. $y$절편 $\\frac{5}{2}$와 $4$는 서로 다르므로 두 직선은 겹치지 않고 평행하다.","확인":"-4","스킬":"G1"}]},"tb-비상중2-p087-1":{"길":"밑각과 이등분된 각을 구한 뒤 삼각형 ABD의 외각으로 x를 구한다","단계":[{"제목":"밑각 ∠ABC 구하기","힌트":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$이면 같은 크기인 두 각은 어느 것이고, 세 각의 합은 몇 도일까?","식":["$\\angle \\mathrm{ABC}=\\angle \\mathrm{C}=\\frac{1}{2}\\times(180^{\\circ}-68^{\\circ})$","$=56^{\\circ}$"],"설명":"이등변삼각형의 두 밑각은 같고, 삼각형의 세 내각의 합은 $180^{\\circ}$이다.","확인":"56","스킬":"S10"},{"제목":"이등분된 ∠ABD 구하기","힌트":"$\\angle \\mathrm{B}$에 찍힌 점 두 개는 각을 어떻게 나눈다는 뜻일까?","식":["$\\angle \\mathrm{ABD}=\\frac{1}{2}\\times56^{\\circ}=28^{\\circ}$"],"설명":"같은 표시는 $\\angle \\mathrm{B}$를 이등분했다는 뜻이다.","확인":"28","스킬":"S10"},{"제목":"삼각형 ABD의 외각으로 x 구하기","고비":true,"힌트":"$\\angle x$는 삼각형 ABD의 어느 두 내각의 합과 같을까?","식":["$\\angle x=\\angle \\mathrm{A}+\\angle \\mathrm{ABD}$","$=68^{\\circ}+28^{\\circ}=96^{\\circ}$"],"설명":"$\\angle x$는 삼각형 ABD에서 점 D의 외각이다. 외각은 이웃하지 않는 두 내각의 합과 같다.","확인":"96","스킬":"S10"}]},"tb-비상중2-p087-2":{"길":"꼭지각의 이등분선의 성질로 선지를 하나씩 따져 옳지 않은 것을 찾는다","단계":[{"제목":"꼭지각의 이등분선의 성질 알기","힌트":"이등변삼각형에서 꼭지각의 이등분선은 밑변을 어떻게 나눌까?","식":["$\\overline{\\mathrm{AD}}$는 밑변 $\\overline{\\mathrm{BC}}$를 수직이등분","$\\overline{\\mathrm{BD}}=\\overline{\\mathrm{CD}}$, $\\angle \\mathrm{ADB}=90^{\\circ}$"],"설명":"꼭지각의 이등분선은 밑변을 수직으로 이등분한다.","확인":null,"스킬":"S2"},{"제목":"그림의 10 cm가 가리키는 변 읽기","고비":true,"힌트":"10 cm 표시는 어느 변을 따라 붙어 있을까?","식":["$10\\,\\mathrm{cm}$는 밑변 $\\overline{\\mathrm{BC}}$의 길이","$\\overline{\\mathrm{BD}}=\\frac{1}{2}\\times10=5\\,(\\mathrm{cm})$"],"설명":"점선이 $\\overline{\\mathrm{BC}}$ 아래에 그려져 있으므로 10 cm는 $\\overline{\\mathrm{BC}}$의 길이이다. $\\overline{\\mathrm{BD}}$는 그 절반이다.","확인":"5","스킬":"S2"},{"제목":"옳지 않은 선지 고르기","힌트":"그림만으로 길이를 알 수 없는 선지는 어느 것일까?","식":["① 밑각, ③ $\\overline{\\mathrm{BD}}=5\\,\\mathrm{cm}$, ④ 수직, ⑤ 합동(SAS)은 모두 옳다","$\\overline{\\mathrm{AB}}$의 길이는 그림에서 알 수 없다 $\\to$ ②"],"설명":"$\\triangle \\mathrm{ABD}$와 $\\triangle \\mathrm{ACD}$는 두 변과 그 끼인각이 같아 합동이다. $\\overline{\\mathrm{AB}}$는 10 cm로 주어지지 않았다.","확인":null,"스킬":"S2"}]},"tb-비상중2-p087-3":{"길":"이등변삼각형의 밑각과 외각의 성질로 각을 차례로 옮긴다","단계":[{"제목":"삼각형 ABC의 외각 ∠DAC 구하기","힌트":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$이므로 $\\angle \\mathrm{ACB}$는 얼마이고, 점 A의 외각 $\\angle \\mathrm{DAC}$는 어느 두 각의 합일까?","식":["$\\angle \\mathrm{ACB}=\\angle \\mathrm{B}=38^{\\circ}$","$\\angle \\mathrm{DAC}=38^{\\circ}+38^{\\circ}=76^{\\circ}$"],"설명":"밑각은 서로 같고, 외각은 이웃하지 않는 두 내각의 합과 같다.","확인":"76","스킬":"S10"},{"제목":"삼각형 CAD의 밑각 ∠D 구하기","힌트":"$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CD}}$이면 같은 크기인 두 각은 어느 것일까?","식":["$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CD}}$이므로 $\\angle \\mathrm{D}=\\angle \\mathrm{DAC}=76^{\\circ}$"],"설명":"$\\overline{\\mathrm{CA}}=\\overline{\\mathrm{CD}}$인 삼각형 CAD의 밑각은 $\\angle \\mathrm{DAC}$와 $\\angle \\mathrm{D}$이다.","확인":null,"스킬":"S10"},{"제목":"삼각형 DBC의 외각으로 x 구하기","고비":true,"힌트":"$\\angle x$는 삼각형 DBC에서 점 C의 외각이다. 어느 두 내각의 합과 같을까?","식":["$\\angle x=\\angle \\mathrm{B}+\\angle \\mathrm{D}$","$=38^{\\circ}+76^{\\circ}=114^{\\circ}$"],"설명":"점 B, A, D가 한 직선 위에 있으므로 $\\angle \\mathrm{DBC}=\\angle \\mathrm{B}$이다. 외각 $\\angle x$는 $\\angle \\mathrm{B}$와 $\\angle \\mathrm{D}$의 합이다.","확인":"114","스킬":"S10"}]},"tb-비상중2-p087-4":{"길":"밑각이 같으면 두 변이 같고, 꼭지각의 이등분선은 밑변을 이등분한다","단계":[{"제목":"AB의 길이 구하기","힌트":"두 밑각이 같은 삼각형에서 길이가 같은 두 변은 어느 것일까?","식":["$\\angle \\mathrm{B}=\\angle \\mathrm{C}$이므로 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$","$\\overline{\\mathrm{AB}}=15\\,\\mathrm{cm}$"],"설명":"두 내각이 같은 삼각형은 이등변삼각형이다. 같은 두 각의 맞은편 변이 서로 같다.","확인":null,"스킬":"S2"},{"제목":"BC의 길이 구하기","고비":true,"힌트":"꼭지각의 이등분선 $\\overline{\\mathrm{AD}}$는 밑변 $\\overline{\\mathrm{BC}}$를 어떻게 나눌까?","식":["$\\overline{\\mathrm{CD}}=\\overline{\\mathrm{BD}}=6\\,\\mathrm{cm}$","$\\overline{\\mathrm{BC}}=6+6=12\\,(\\mathrm{cm})$"],"설명":"꼭지각의 이등분선은 밑변을 이등분하므로 점 D는 $\\overline{\\mathrm{BC}}$의 중점이다.","확인":"12","스킬":"S2"},{"제목":"삼각형 ABC의 둘레 구하기","힌트":"세 변 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{BC}}$, $\\overline{\\mathrm{CA}}$의 길이를 모두 더하면?","식":["$15+12+15=42\\,(\\mathrm{cm})$"],"설명":"세 변의 길이의 합이 둘레이다.","확인":"42","스킬":"S2"}]},"tb-비상중2-p087-5":{"길":"각을 모두 구해 숨은 이등변삼각형 두 개를 찾아 길이를 옮긴다","단계":[{"제목":"밑각과 이등분된 각 구하기","힌트":"$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}$, $\\angle \\mathrm{A}=36^{\\circ}$일 때 $\\angle \\mathrm{B}$는 몇 도일까?","식":["$\\angle \\mathrm{B}=\\angle \\mathrm{ACB}=\\frac{1}{2}\\times(180^{\\circ}-36^{\\circ})=72^{\\circ}$","$\\angle \\mathrm{ACD}=\\angle \\mathrm{DCB}=\\frac{1}{2}\\times72^{\\circ}=36^{\\circ}$"],"설명":"두 밑각의 크기는 같다. 점 두 개 표시는 $\\angle \\mathrm{C}$를 이등분했다는 뜻이다.","확인":"72","스킬":"S10"},{"제목":"삼각형 ACD가 이등변삼각형임 알기","힌트":"삼각형 ACD에서 크기가 같은 두 각은 어느 것일까?","식":["$\\angle \\mathrm{A}=\\angle \\mathrm{ACD}=36^{\\circ}$","$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{CD}}$"],"설명":"두 내각이 같으면 그 두 각의 맞은편 변이 서로 같다.","확인":null,"스킬":"S10"},{"제목":"삼각형 BCD가 이등변삼각형임 알기","고비":true,"힌트":"삼각형 BCD의 세 각의 합이 $180^{\\circ}$임을 이용해 $\\angle \\mathrm{BDC}$를 구하면?","식":["$\\angle \\mathrm{BDC}=180^{\\circ}-72^{\\circ}-36^{\\circ}=72^{\\circ}$","$\\angle \\mathrm{B}=\\angle \\mathrm{BDC}$이므로 $\\overline{\\mathrm{CD}}=\\overline{\\mathrm{CB}}$"],"설명":"$\\angle \\mathrm{B}$와 $\\angle \\mathrm{BDC}$가 같으므로 그 맞은편 변 $\\overline{\\mathrm{CD}}$와 $\\overline{\\mathrm{CB}}$가 같다.","확인":null,"스킬":"S10"},{"제목":"길이를 옮겨 AD 구하기","힌트":"$\\overline{\\mathrm{AD}}$, $\\overline{\\mathrm{CD}}$, $\\overline{\\mathrm{CB}}$의 관계를 이으면 $\\overline{\\mathrm{AD}}$는 얼마일까?","식":["$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{CD}}=\\overline{\\mathrm{CB}}=8\\,\\mathrm{cm}$"],"설명":"$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{CD}}$, $\\overline{\\mathrm{CD}}=\\overline{\\mathrm{CB}}$이고 $\\overline{\\mathrm{CB}}=8\\,\\mathrm{cm}$이다.","확인":"8","스킬":"S10"}]},"tb-비상중2-p087-6":{"길":"엇각과 접은 각이 같음을 이용해 삼각형 ABC가 이등변삼각형임을 보인다","단계":[{"제목":"엇각으로 ∠ACB와 ∠DBC 비교하기","힌트":"$\\overline{\\mathrm{AC}}\\parallel\\overline{\\mathrm{BD}}$이다. 직선 BC가 두 평행선과 만나서 생기는 엇각의 크기는 어떻게 될까?","식":["$\\overline{\\mathrm{AC}}\\parallel\\overline{\\mathrm{BD}}$이므로 $\\angle \\mathrm{ACB}=\\angle \\mathrm{DBC}$ (엇각)"],"설명":"접기 전 직사각형의 윗변과 아랫변이 평행하므로 $\\overline{\\mathrm{AC}}$와 $\\overline{\\mathrm{BD}}$가 평행하다.","확인":null,"스킬":"S10"},{"제목":"접은 각으로 ∠ABC와 ∠DBC 비교하기","힌트":"종이를 접으면 접은 선 BC를 사이에 두고 겹치는 두 각의 크기는 어떻게 될까?","식":["접은 각이므로 $\\angle \\mathrm{ABC}=\\angle \\mathrm{DBC}$"],"설명":"접은 선을 기준으로 겹쳐지는 두 각은 크기가 같다.","확인":null,"스킬":"S10"},{"제목":"이등변삼각형임을 알고 AB 구하기","고비":true,"힌트":"$\\angle \\mathrm{ACB}$와 $\\angle \\mathrm{ABC}$가 같으면 길이가 같은 두 변은 어느 것일까?","식":["$\\angle \\mathrm{ACB}=\\angle \\mathrm{ABC}$이므로 $\\triangle \\mathrm{ABC}$는 이등변삼각형","$\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AC}}=9\\,\\mathrm{cm}$"],"설명":"두 각이 같은 삼각형에서 그 두 각의 맞은편 변은 서로 같다. $\\overline{\\mathrm{BC}}=7\\,\\mathrm{cm}$는 풀이에 쓰이지 않는다.","확인":"9","스킬":"S10"}]},"tb-비상중2-p088-1":{"길":"대응하는 변과 각을 짝지어 직각삼각형의 합동 조건에 맞는 선지를 찾는다","단계":[{"제목":"삼각형 FED의 빗변과 각 읽기","힌트":"직각이 있는 점 E의 맞은편 변은 어느 것이고, 길이와 각의 크기는 얼마일까?","식":["$\\triangle \\mathrm{FED}$: 빗변 $\\overline{\\mathrm{FD}}=8\\,\\mathrm{cm}$, $\\angle \\mathrm{F}=30^{\\circ}$","대응: $\\mathrm{A}\\leftrightarrow\\mathrm{F}$, $\\mathrm{B}\\leftrightarrow\\mathrm{E}$, $\\mathrm{C}\\leftrightarrow\\mathrm{D}$"],"설명":"$\\triangle \\mathrm{ABC}\\equiv\\triangle \\mathrm{FED}$이므로 꼭짓점 순서대로 대응한다. 직각 맞은편이 빗변이다.","확인":null,"스킬":"S2"},{"제목":"합동에 필요한 조건 정하기","힌트":"직각삼각형에서 빗변의 길이와 한 예각의 크기가 같으면 어떤 합동일까?","식":["$\\triangle \\mathrm{ABC}$에서 필요한 조건: $\\overline{\\mathrm{AC}}=8\\,\\mathrm{cm}$, $\\angle \\mathrm{A}=30^{\\circ}$","RHA 합동"],"설명":"직각삼각형은 빗변의 길이와 한 예각의 크기가 각각 같으면 합동이다.","확인":null,"스킬":"S2"},{"제목":"조건을 만족하는 선지 고르기","고비":true,"힌트":"④에서 $\\angle \\mathrm{C}=60^{\\circ}$이면 $\\angle \\mathrm{A}$는 몇 도일까?","식":["④ $\\angle \\mathrm{A}=180^{\\circ}-(90^{\\circ}+60^{\\circ})=30^{\\circ}$","$\\overline{\\mathrm{AC}}=8\\,\\mathrm{cm}$는 빗변이므로 RHA 합동 $\\to$ ④"],"설명":"④는 빗변과 $\\angle \\mathrm{A}=30^{\\circ}$가 모두 정해진다. 다른 선지는 대응하는 빗변이나 예각이 함께 정해지지 않는다.","확인":null,"스킬":"S2"}]},"tb-비상중2-p088-2":{"길":"각의 이등분선 위 점에서 내린 수선으로 직각삼각형의 합동을 찾아 BD를 구한다","단계":[{"제목":"합동인 두 직각삼각형 찾기","고비":true,"힌트":"삼각형 BCE와 BDE에서 직각, 공통인 변, 같은 크기인 각은 무엇일까?","식":["$\\angle \\mathrm{C}=\\angle \\mathrm{BDE}=90^{\\circ}$, $\\overline{\\mathrm{BE}}$는 공통, $\\angle \\mathrm{CBE}=\\angle \\mathrm{DBE}$","$\\triangle \\mathrm{BCE}\\equiv\\triangle \\mathrm{BDE}$ (RHA 합동)"],"설명":"$\\overline{\\mathrm{BE}}$는 두 직각삼각형의 공통인 빗변이고, $\\angle \\mathrm{B}$의 이등분선이므로 $\\angle \\mathrm{CBE}=\\angle \\mathrm{DBE}$이다.","확인":null,"스킬":"S2"},{"제목":"대응변으로 BD의 길이 구하기","힌트":"합동인 두 삼각형에서 $\\overline{\\mathrm{BC}}$에 대응하는 변은 어느 것일까?","식":["$\\overline{\\mathrm{BD}}=\\overline{\\mathrm{BC}}=9\\,\\mathrm{cm}$"],"설명":"$\\overline{\\mathrm{BC}}$는 $\\overline{\\mathrm{BD}}$와 대응하는 변이므로 길이가 같다.","확인":null,"스킬":"S2"},{"제목":"AD의 길이 구하기","힌트":"점 D는 $\\overline{\\mathrm{AB}}$ 위에 있다. $\\overline{\\mathrm{AB}}$에서 $\\overline{\\mathrm{BD}}$를 빼면?","식":["$\\overline{\\mathrm{AD}}=\\overline{\\mathrm{AB}}-\\overline{\\mathrm{BD}}=14-9=5\\,(\\mathrm{cm})$"],"설명":"$\\overline{\\mathrm{AB}}$를 $\\overline{\\mathrm{AD}}$와 $\\overline{\\mathrm{BD}}$로 나누어 생각한다.","확인":"5","스킬":"S2"}]},"tb-비상중2-p088-3":{"길":"수선의 발이 만드는 두 직각삼각형의 합동을 보이고 대응변으로 길이를 옮긴다","단계":[{"제목":"엇갈린 두 각이 같음 보이기","고비":true,"힌트":"삼각형 CDA의 두 예각의 합과, 직선 $l$ 위의 점 A에서 $\\angle \\mathrm{DAC}$와 $\\angle \\mathrm{EAB}$의 합은 각각 몇 도일까?","식":["$\\angle \\mathrm{DCA}+\\angle \\mathrm{DAC}=90^{\\circ}$","$\\angle \\mathrm{DAC}+\\angle \\mathrm{EAB}=180^{\\circ}-90^{\\circ}=90^{\\circ}$","$\\angle \\mathrm{DCA}=\\angle \\mathrm{EAB}$"],"설명":"삼각형 CDA는 직각삼각형이라 두 예각의 합이 $90^{\\circ}$이다. 직선 위의 각은 $180^{\\circ}$이고 $\\angle \\mathrm{A}=90^{\\circ}$이므로 나머지 두 각의 합도 $90^{\\circ}$이다. 직선 $l$이 삼각형 밖을 지나는 그림으로 본다.","확인":null,"스킬":"S2"},{"제목":"삼각형 CDA와 AEB의 합동 보이기","힌트":"두 직각삼각형에서 직각, 빗변의 길이, 같은 예각을 짝지으면 어떤 합동 조건일까?","식":["$\\angle \\mathrm{CDA}=\\angle \\mathrm{AEB}=90^{\\circ}$, $\\overline{\\mathrm{CA}}=\\overline{\\mathrm{AB}}$, $\\angle \\mathrm{DCA}=\\angle \\mathrm{EAB}$","$\\triangle \\mathrm{CDA}\\equiv\\triangle \\mathrm{AEB}$ (RHA 합동)"],"설명":"$\\overline{\\mathrm{CA}}$와 $\\overline{\\mathrm{AB}}$는 각각 두 삼각형의 빗변이다.","확인":null,"스킬":"S2"},{"제목":"대응변으로 DE의 길이 구하기","힌트":"$\\overline{\\mathrm{DA}}$, $\\overline{\\mathrm{AE}}$와 각각 같은 변은 어느 것일까?","식":["$\\overline{\\mathrm{DA}}=\\overline{\\mathrm{EB}}=6\\,\\mathrm{cm}$, $\\overline{\\mathrm{AE}}=\\overline{\\mathrm{CD}}=8\\,\\mathrm{cm}$","$\\overline{\\mathrm{DE}}=\\overline{\\mathrm{DA}}+\\overline{\\mathrm{AE}}=6+8=14\\,(\\mathrm{cm})$"],"설명":"점 A는 $\\overline{\\mathrm{DE}}$ 위에 있으므로 $\\overline{\\mathrm{DE}}$는 두 선분의 합이다.","확인":"14","스킬":"S2"}]},"tb-비상중2-p088-4":{"길":"빗변 AD를 함께 쓰는 두 직각삼각형의 합동으로 ∠BAC를 구한 뒤 ∠x를 구한다","단계":[{"제목":"합동인 두 직각삼각형 찾기","고비":true,"힌트":"삼각형 ABD와 AED에서 직각, 같은 길이의 변, 공통인 변은 무엇일까?","식":["$\\angle \\mathrm{B}=\\angle \\mathrm{AED}=90^{\\circ}$, $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{AE}}$, $\\overline{\\mathrm{AD}}$는 공통","$\\triangle \\mathrm{ABD}\\equiv\\triangle \\mathrm{AED}$ (RHS 합동)"],"설명":"$\\overline{\\mathrm{AD}}$는 두 직각삼각형의 공통인 빗변이고, 빗변과 다른 한 변이 각각 같다.","확인":null,"스킬":"S2"},{"제목":"∠BAC 구하기","힌트":"합동이면 $\\angle \\mathrm{EAD}$는 $\\angle \\mathrm{BAD}$와 어떤 관계일까? $\\angle \\mathrm{BAC}$는 두 각을 합한 각이다.","식":["$\\angle \\mathrm{EAD}=\\angle \\mathrm{BAD}=25^{\\circ}$","$\\angle \\mathrm{BAC}=25^{\\circ}+25^{\\circ}=50^{\\circ}$"],"설명":"대응하는 각의 크기가 같으므로 $\\overline{\\mathrm{AD}}$는 $\\angle \\mathrm{BAC}$를 이등분한다.","확인":"50","스킬":"S2"},{"제목":"삼각형 ABC에서 ∠x 구하기","힌트":"삼각형 ABC의 세 각의 합이 $180^{\\circ}$이다. $\\angle \\mathrm{B}$와 $\\angle \\mathrm{BAC}$를 빼면?","식":["$\\angle x=180^{\\circ}-(90^{\\circ}+50^{\\circ})=40^{\\circ}$"],"설명":"$\\angle x$는 삼각형 ABC의 $\\angle \\mathrm{C}$이다.","확인":"40","스킬":"S2"}]},"tb-비상중2-p088-5":{"길":"직각이등변삼각형 BDE에서 ED를 구하고 합동인 두 삼각형으로 EC에 옮긴다","단계":[{"제목":"∠B 구하기","힌트":"$\\overline{\\mathrm{AC}}=\\overline{\\mathrm{BC}}$, $\\angle \\mathrm{C}=90^{\\circ}$인 삼각형 ABC에서 $\\angle \\mathrm{B}$는 몇 도일까?","식":["$\\angle \\mathrm{B}=\\frac{1}{2}\\times(180^{\\circ}-90^{\\circ})=45^{\\circ}$"],"설명":"이등변삼각형의 두 밑각은 같고 세 각의 합은 $180^{\\circ}$이다.","확인":"45","스킬":"S2"},{"제목":"삼각형 DBE에서 ED 구하기","힌트":"$\\angle \\mathrm{B}=45^{\\circ}$, $\\angle \\mathrm{BDE}=90^{\\circ}$이면 $\\angle \\mathrm{DEB}$는 몇 도이고, 같은 두 각의 맞은편 변은 어느 것일까?","식":["$\\angle \\mathrm{DEB}=180^{\\circ}-90^{\\circ}-45^{\\circ}=45^{\\circ}$","$\\angle \\mathrm{B}=\\angle \\mathrm{DEB}$이므로 $\\overline{\\mathrm{ED}}=\\overline{\\mathrm{BD}}=5\\,\\mathrm{cm}$"],"설명":"두 내각이 같으면 맞은편 변의 길이가 같으므로 삼각형 DBE는 직각이등변삼각형이다.","확인":null,"스킬":"S2"},{"제목":"합동으로 EC의 길이 구하기","고비":true,"힌트":"삼각형 ADE와 ACE에서 직각, 공통인 변, 같은 길이의 변은 무엇일까?","식":["$\\angle \\mathrm{ADE}=\\angle \\mathrm{C}=90^{\\circ}$, $\\overline{\\mathrm{AE}}$는 공통, $\\overline{\\mathrm{AD}}=\\overline{\\mathrm{AC}}$","$\\triangle \\mathrm{ADE}\\equiv\\triangle \\mathrm{ACE}$ (RHS 합동)","$\\overline{\\mathrm{EC}}=\\overline{\\mathrm{ED}}=5\\,\\mathrm{cm}$"],"설명":"$\\overline{\\mathrm{AE}}$는 두 직각삼각형의 공통인 빗변이다. 합동이므로 대응변 $\\overline{\\mathrm{EC}}$와 $\\overline{\\mathrm{ED}}$의 길이가 같다.","확인":"5","스킬":"S2"}]},"tb-비상중2-p088-6":{"길":"직각삼각형 PAO와 PBO의 합동을 확인하고 성립하지 않는 선지를 고른다","단계":[{"제목":"삼각형 PAO와 PBO의 합동 보이기","힌트":"두 삼각형의 직각, 공통인 변, 같은 크기인 각은 무엇일까?","식":["$\\angle \\mathrm{OAP}=\\angle \\mathrm{OBP}=90^{\\circ}$, $\\overline{\\mathrm{OP}}$는 공통, $\\angle \\mathrm{AOP}=\\angle \\mathrm{BOP}$","$\\triangle \\mathrm{PAO}\\equiv\\triangle \\mathrm{PBO}$ (RHA 합동)","대응변·대응각이 같으므로 ①, ②, ③, ⑤는 성립"],"설명":"합동이면 $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$, $\\overline{\\mathrm{PA}}=\\overline{\\mathrm{PB}}$, $\\angle \\mathrm{OPA}=\\angle \\mathrm{OPB}$이다.","확인":null,"스킬":"S2"},{"제목":"빗변과 다른 변의 길이 비교하기","고비":true,"힌트":"삼각형 PAO에서 $\\overline{\\mathrm{OP}}$는 어느 변이고, 직각삼각형에서 가장 긴 변은 무엇일까?","식":["$\\overline{\\mathrm{OP}}$는 직각의 맞은편인 빗변","빗변이 가장 길므로 $\\overline{\\mathrm{OP}}>\\overline{\\mathrm{OA}}$ $\\to$ ④"],"설명":"직각삼각형에서 빗변은 다른 두 변보다 길다. 따라서 $\\overline{\\mathrm{OP}}=\\overline{\\mathrm{OA}}$는 성립하지 않는다.","확인":null,"스킬":"S2"}]},"tb-비상중2-p089-1":{"길":"외심의 성질로 선지를 하나씩 확인해 성립하지 않는 것을 찾는다","단계":[{"제목":"외심의 성질 정리하기","힌트":"외심은 세 꼭짓점까지의 거리가 어떤 관계일까?","식":["외심 $\\mathrm{O}$는 세 꼭짓점까지의 거리가 같다 $\\to$ $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}=\\overline{\\mathrm{OC}}$ (①)","$\\mathrm{O}$에서 각 변에 내린 수선은 그 변을 이등분 $\\to$ $\\overline{\\mathrm{AD}}=\\overline{\\mathrm{BD}}$ (③)"],"설명":"외심은 세 변의 수직이등분선의 교점이므로 세 꼭짓점에서 같은 거리에 있다.","확인":null,"스킬":"S7"},{"제목":"나머지 선지가 외심의 성질로 성립하는지 확인하기","힌트":"$\\overline{\\mathrm{OB}}=\\overline{\\mathrm{OC}}$이면 삼각형 OBC의 두 밑각은 어떻게 될까?","식":["④ $\\overline{\\mathrm{OB}}=\\overline{\\mathrm{OC}}$이므로 $\\angle \\mathrm{OBE}=\\angle \\mathrm{OCE}$","⑤ $\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OC}}$, $\\overline{\\mathrm{OF}}$ 공통, $\\angle \\mathrm{OFA}=\\angle \\mathrm{OFC}=90^{\\circ}$이므로 $\\triangle \\mathrm{OFA}\\equiv\\triangle \\mathrm{OFC}$"],"설명":"④는 이등변삼각형 OBC의 밑각이고, ⑤는 직각삼각형의 빗변과 공통인 변이 같은 RHS 합동이다.","확인":null,"스킬":"S7"},{"제목":"성립하지 않는 선지 고르기","고비":true,"힌트":"세 변까지의 거리가 같은 점은 외심일까, 내심일까?","식":["$\\overline{\\mathrm{OD}}$, $\\overline{\\mathrm{OE}}$, $\\overline{\\mathrm{OF}}$는 $\\mathrm{O}$에서 세 변까지의 거리","세 변까지의 거리가 같은 점은 내심이므로 외심에서는 반드시 성립하지 않는다 $\\to$ ②"],"설명":"외심은 세 꼭짓점까지의 거리가 같고, 내심은 세 변까지의 거리가 같다.","확인":null,"스킬":"S7"}]},"tb-비상중2-p089-2":{"길":"OA=OB=OC로 이등변삼각형을 만들어 각을 이어 ∠AOB를 구한다","단계":[{"제목":"외심에서 이등변삼각형 찾기","힌트":"OC를 그으면 외심에서 세 꼭짓점까지의 거리는 어떤 관계이고, 이때 같은 크기인 각은 무엇일까?","식":["$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}=\\overline{\\mathrm{OC}}$","$\\angle \\mathrm{OCA}=\\angle \\mathrm{OAC}=30^{\\circ}$, $\\angle \\mathrm{OCB}=\\angle \\mathrm{OBC}=20^{\\circ}$"],"설명":"외심은 세 꼭짓점까지의 거리가 같으므로 삼각형 OAC, OBC는 이등변삼각형이고 밑각이 서로 같다.","확인":null,"스킬":"S7"},{"제목":"내각의 합으로 ∠OAB 구하기","고비":true,"힌트":"$\\angle \\mathrm{OAB}=\\angle \\mathrm{OBA}=a$로 놓으면 삼각형 ABC의 세 각의 합에서 $a$는 얼마일까?","식":["$\\angle \\mathrm{OAB}=\\angle \\mathrm{OBA}=a$ ($\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$)","$(30^{\\circ}+a)+(20^{\\circ}+a)+(30^{\\circ}+20^{\\circ})=180^{\\circ}$","$a=40^{\\circ}$"],"설명":"삼각형 ABC의 세 각은 $\\angle \\mathrm{A}=30^{\\circ}+a$, $\\angle \\mathrm{B}=20^{\\circ}+a$, $\\angle \\mathrm{C}=30^{\\circ}+20^{\\circ}$이다. 합이 $180^{\\circ}$이므로 $2a=80^{\\circ}$이다.","확인":"40","스킬":"S7"},{"제목":"삼각형 OAB에서 ∠x 구하기","힌트":"삼각형 OAB의 세 각의 합에서 $\\angle \\mathrm{AOB}$는 얼마일까?","식":["$\\angle x=180^{\\circ}-(40^{\\circ}+40^{\\circ})=100^{\\circ}$"],"설명":"$\\angle x$는 삼각형 OAB의 $\\angle \\mathrm{AOB}$이다.","확인":"100","스킬":"S7"}]},"tb-비상중2-p089-3":{"길":"외심이 변 위에 있으면 그 변이 빗변이므로 맞은편 각이 90°임을 이용한다","단계":[{"제목":"∠BAC의 크기 알아내기","고비":true,"힌트":"외심이 변 BC 위에 있으면 $\\overline{\\mathrm{BC}}$는 어떤 변이고, $\\angle \\mathrm{BAC}$는 몇 도일까?","식":["외심이 $\\overline{\\mathrm{BC}}$ 위에 있다 $\\to$ $\\overline{\\mathrm{BC}}$가 빗변","$\\angle \\mathrm{BAC}=90^{\\circ}$"],"설명":"직각삼각형의 외심은 빗변의 중점이다. 거꾸로 외심이 한 변 위에 있으면 그 변이 빗변이고, 맞은편 각이 직각이다.","확인":"90","스킬":"S7"},{"제목":"∠OAB 구하기","힌트":"$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$이면 삼각형 OAB에서 $\\angle \\mathrm{OAB}$와 같은 크기의 각은 무엇일까?","식":["$\\overline{\\mathrm{OA}}=\\overline{\\mathrm{OB}}$이므로 $\\angle \\mathrm{OAB}=\\angle \\mathrm{B}=53^{\\circ}$"],"설명":"외심은 세 꼭짓점까지의 거리가 같으므로 삼각형 OAB는 이등변삼각형이고 밑각이 같다.","확인":null,"스킬":"S7"},{"제목":"∠x 구하기","힌트":"$\\angle \\mathrm{BAC}$에서 $\\angle \\mathrm{OAB}$를 빼면?","식":["$\\angle x=\\angle \\mathrm{BAC}-\\angle \\mathrm{OAB}=90^{\\circ}-53^{\\circ}=37^{\\circ}$"],"설명":"$\\angle x$는 $\\angle \\mathrm{BAC}$ 중 $\\angle \\mathrm{OAB}$를 제외한 나머지 각이다.","확인":"37","스킬":"S7"}]}});
